67	namespace TritonToStructured {
68	using namespace mlir;
69	using namespace triton;
70	
71	bool isMultiple(const OpFoldResult &dividend, const OpFoldResult &divisor) {
72	  auto staticDividend = getIntAttr(dividend);
73	  auto staticDivisor = getIntAttr(divisor);
74	  if (!staticDividend || !staticDivisor) {
75	    return false;
76	  }
77	  return staticDividend.value() % staticDivisor.value() == 0;
78	}
79	
80	bool isEqual(const OpFoldResult &ofr1, const OpFoldResult &ofr2) {
81	  auto staticOfr1 = getIntAttr(ofr1);
82	  auto staticOfr2 = getIntAttr(ofr2);
83	  return staticOfr1 == staticOfr2;
84	}
85	
86	bool isLess(const OpFoldResult &ofr1, const OpFoldResult &ofr2) {
87	  auto staticOfr1 = getIntAttr(ofr1);
88	  auto staticOfr2 = getIntAttr(ofr2);
89	  // When sorting for permute, the value determined at runtime
90	  // is greater than the value determined at compile time.
91	  if (!staticOfr1 && !staticOfr2) {
92	    return false; // keep relative order (stable_sort)
93	  }
94	  if (!staticOfr1 && staticOfr2) {
95	    return false; // dynamic > static
96	  }
97	  if (staticOfr1 && !staticOfr2) {
98	    return true; // static < dynamic
99	  }
100	  return staticOfr1.value() < staticOfr2.value();
101	}
102	
103	bool isGreater(const OpFoldResult &ofr1, const OpFoldResult &ofr2) {
104	  auto staticOfr1 = getIntAttr(ofr1);
105	  auto staticOfr2 = getIntAttr(ofr2);
106	  // When sorting for permute, the value determined at runtime
107	  // is greater than the value determined at compile time.
108	  if (!staticOfr1 && !staticOfr2) {
109	    return false; // keep relative order (stable_sort)
110	  }
111	  if (!staticOfr1 && staticOfr2) {
112	    return true; // dynamic > static
113	  }
114	  if (staticOfr1 && !staticOfr2) {
115	    return false; // static < dynamic
116	  }
117	  return staticOfr1.value() > staticOfr2.value();
118	}
