120	void StateInfo::dump() const {
121	  llvm::dbgs() << "StateInfo: \n";
122	  llvm::dbgs() << "dimIndex = " << dimIndex << "\n";
123	  llvm::dbgs() << "shape = " << shape << "\n";
124	  llvm::dbgs() << "stride = " << stride << "\n";
