127	void PtrState::dump() const {
128	  llvm::dbgs() << "PtrState: \n";
129	  llvm::dbgs() << "source:" << source << "\n";
130	  llvm::dbgs() << "scalar:" << offset << "\n";
131	  llvm::dbgs() << "size: [";
132	  for (auto size : sizes)
133	    llvm::dbgs() << size << ", ";
134	  llvm::dbgs() << "]\n";
135	  llvm::dbgs() << "shouldLinearize: " << shouldLinearize << "\n";
136	  llvm::dbgs() << "isPermuted: " << isPermuted << "\n";
137	  llvm::dbgs() << "isBlockPtr: " << isBlockPtr() << "\n";
138	
139	  llvm::dbgs() << "permuteIds: [";
140	  for (auto id : permuteIds)
141	    llvm::dbgs() << id << ", ";
142	  llvm::dbgs() << "]\n";
143	  llvm::dbgs() << "order: [";
144	  for (auto id : order)
145	    llvm::dbgs() << id << ", ";
146	  llvm::dbgs() << "]\n";
147	
148	  llvm::dbgs() << "stateInfo:\n";
149	  llvm::dbgs() << "\n";
150	  for (auto info : stateInfo) {
