157	bool PtrState::isEmpty() const {
158	  return (stateInfo.empty() && !source && !offset);
159	}
160	
161	bool PtrState::isScalar() const {
162	  bool scalar = true;
163	  for (auto info : stateInfo) {
164	    auto staticStride = getIntAttr(info.stride);
165	    if (!staticStride.has_value() || staticStride.value() != 0)
166	      scalar = false;
167	  }
168	  return scalar && (offset || source);
169	}
170	
171	bool PtrState::hasSource() const { return source != nullptr; }
172	
173	bool PtrState::isBlockPtr() const { return !order.empty(); }
174	
175	bool PtrState::isSameSizeAs(const PtrState &x) const {
176	  if (this->sizes.size() != x.sizes.size())
177	    return false;
178	
179	  for (size_t i = 0; i < this->sizes.size(); ++i) {
180	    if (this->sizes[i] != x.sizes[i])
181	      return false;
182	  }
183	  return true;
184	}
185	
186	void PtrState::updatePtrState(SmallVector<StateInfo> stateInfo,
187	                              SmallVector<OpFoldResult> sizes, Value source,
188	                              OpFoldResult offset, const Location loc,
189	                              OpBuilder &builder, bool shouldLinearize) {
190	  this->stateInfo = stateInfo;
191	  this->sizes = sizes;
192	  this->source = source;
193	  this->offset = offset;
194	  this->shouldLinearize = shouldLinearize;
195	  this->normalizeState(loc, builder);
196	}
197	
198	void PtrState::normalizeState(const Location loc, OpBuilder &builder) {
199	  SmallVector<StateInfo> newStateInfo;
200	  auto zeroAttr = builder.getIndexAttr(0);
201	
202	  // merge continuous zero strides
203	  // e.g., stride [0, 0, 1] shape [4, 32, 16]  --> stride [0, 1] shape [128, 16]
204	  for (auto it = this->stateInfo.begin(); it != this->stateInfo.end(); ++it) {
205	    while (it != this->stateInfo.end() && isZero(it->stride)) {
206	      auto newShape = it->shape;
207	      auto dimIndex = it->dimIndex;
208	      for (++it; it != this->stateInfo.end() && isZero(it->stride) &&
209	                 it->dimIndex == dimIndex;
210	           ++it) {
211	        newShape = mulOpFoldResult(newShape, it->shape, loc, builder);
212	      }
213	      newStateInfo.emplace_back(zeroAttr, newShape, dimIndex);
214	    }
215	    if (it == this->stateInfo.end())
216	      break;
217	    // if the info is the only one with oriSize 1 in this dimension, skip it
218	    // e.g., stride [0, 1] shape [1, 128] sizes [1, 128] do not delete the first
219	    // info
220	    if (isOne(it->shape) && !isOne(sizes[it->dimIndex]))
221	      continue;
222	    newStateInfo.emplace_back(*it);
223	  }
224	
225	  this->stateInfo = newStateInfo;
226	}
227	
228	LogicalResult PtrAnalysis::visitOperandAddptr(triton::AddPtrOp addptrOp,
229	                                              PtrState &state,
230	                                              const Location loc,
231	                                              OpBuilder &builder) {
232	  if (!state.isEmpty()) {
233	    LLVM_DEBUG({
234	      addptrOp.emitError(
235	          "PtrAnalysis: PtrState should be empty when visiting addptr");
236	    });
237	    return failure();
238	  }
239	
240	  LLVM_DEBUG({
241	    llvm::dbgs() << "----------------------------------------------\n";
242	    llvm::dbgs() << "Visit addptr operation: " << addptrOp << "\n";
243	  });
244	
245	  PtrState ptrState;
246	  if (visitOperand(addptrOp.getPtr(), ptrState, addptrOp.getLoc(), builder)
247	          .failed()) {
248	    return failure();
249	  }
250	
251	  PtrState offsetState;
252	  if (visitOperand(addptrOp.getOffset(), offsetState, addptrOp.getLoc(),
253	                   builder)
254	          .failed()) {
255	    return failure();
256	  }
257	
258	  LLVM_DEBUG({
259	    llvm::dbgs() << "----------------------------------------------\n";
260	    llvm::dbgs() << "Before visiting addptr operands: \n";
261	    llvm::dbgs() << "PtrState: \n";
262	    ptrState.dump();
263	    llvm::dbgs() << "OffsetState: \n";
264	    offsetState.dump();
265	    llvm::dbgs() << "----------------------------------------------\n";
266	  });
267	
268	  if (!ptrState.source) {
269	    LLVM_DEBUG({
270	      addptrOp.emitError("ptr field should provide source / base pointer");
271	    });
272	    return failure();
273	  }
274	  return state.addState(ptrState, offsetState, addptrOp, builder);
275	}
276	
277	LogicalResult
278	PtrAnalysis::visitOperandMakeTensorPtr(triton::MakeTensorPtrOp makeTPtrOp,
279	                                       PtrState &state, const Location loc,
280	                                       OpBuilder &builder) {
281	  if (!state.isEmpty()) {
282	    makeTPtrOp.emitError(
283	        "PtrAnalysis: PtrState should be empty when visiting make_tensor_ptr");
284	    return failure();
285	  }
286	  if (makeTPtrOp.getOrder().empty()) {
287	    LLVM_DEBUG(makeTPtrOp->emitRemark(
288	        "PtrAnalysis: expect tt.make_tensor_ptr to have order field set"));
289	    return failure();
290	  }
291	
292	  // Build:
293	  //   - stateInfo: per-dimension (stride, shape, dimIndex) of the parent tensor
294	  //   - sizes: original tensor shape of the block
295	  //   - dimOffsets: the offset to the block in the parent tensor
296	  state.source = makeTPtrOp.getBase();
297	  state.dimOffsets = makeTPtrOp.getOffsets();
298	  state.order = SmallVector<size_t>(makeTPtrOp.getOrder());
299	
300	  auto resType = cast<triton::PointerType>(makeTPtrOp.getResult().getType());
301	  auto pointeeType = cast<ShapedType>(resType.getPointeeType());
302	  auto pointeeShape = pointeeType.getShape();
303	  const int64_t rank = pointeeType.getRank();
304	
305	  SmallVector<StateInfo> newStateInfo;
306	  for (int64_t i = 0; i < rank; i++) {
307	    state.sizes.push_back(builder.getIndexAttr(pointeeShape[i]));
308	    newStateInfo.emplace_back(makeTPtrOp.getStrides()[i],
309	                              makeTPtrOp.getShape()[i], i);
310	  }
311	  state.stateInfo = newStateInfo;
312	
313	  assert(state.isBlockPtr() &&
314	         "tt.make_tensor_ptr pointer state should describe a block pointer");
315	
316	  return success();
317	}
