319	bool PtrAnalysis::operandIsScalar(Value operand) {
320	  auto tensorType = dyn_cast<mlir::RankedTensorType>(operand.getType());
321	  auto elementType =
322	      tensorType ? tensorType.getElementType() : operand.getType();
323	  bool isScalar = true;
324	  if (tensorType) {
325	    for (size_t i = 0; i < tensorType.getRank() && isScalar; ++i) {
326	      isScalar = tensorType.getDimSize(i) == 1;
327	    }
328	  }
329	  return isScalar &&
330	         (isa<IntegerType>(elementType) || isa<IndexType>(elementType));
331	}
332	
333	LogicalResult PtrAnalysis::initStateByScalar(Value operand, PtrState &state,
334	                                             const Location loc,
335	                                             OpBuilder &builder) {
336	  OpFoldResult newOffset;
337	  SmallVector<OpFoldResult> newSizes;
338	  SmallVector<StateInfo> newStateInfo;
339	  if (isa<IntegerType>(operand.getType())) {
340	    OpBuilder::InsertionGuard guard(builder);
341	    if (!isa<BlockArgument>(operand) && operand.getDefiningOp()) {
342	      builder.setInsertionPointAfter(operand.getDefiningOp());
343	    }
344	    auto castOp = builder.create<arith::IndexCastOp>(
345	        loc, builder.getIndexType(), operand);
346	    newOffset = castOp.getResult();
347	  } else if (isa<IndexType>(operand.getType())) {
348	    newOffset = operand;
349	  } else {
350	    auto tensorType = dyn_cast<mlir::RankedTensorType>(operand.getType());
351	    auto index = builder.create<mlir::arith::ConstantIndexOp>(loc, 0);
352	    auto zeroAttr = builder.getIndexAttr(0);
353	    auto oneAttr = builder.getIndexAttr(1);
354	    SmallVector<mlir::Value> indices;
355	    for (size_t i = 0; i < tensorType.getRank(); ++i) {
356	      indices.push_back(index);
357	      newSizes.emplace_back(oneAttr);
358	      newStateInfo.emplace_back(zeroAttr, oneAttr, i);
359	    }
360	    auto extractedElement =
361	        builder.create<mlir::tensor::ExtractOp>(loc, operand, indices);
362	    newOffset = extractedElement.getResult();
363	  }
364	  state.updatePtrState(newStateInfo, newSizes, nullptr, newOffset, loc,
365	                       builder);
366	  return success();
367	}
