369	LogicalResult PtrAnalysis::initStateByPointer(Value operand, PtrState &state,
370	                                              const Location loc,
371	                                              OpBuilder &builder) {
372	  Value newSource;
373	  SmallVector<OpFoldResult> newSizes;
374	  SmallVector<StateInfo> newStateInfo;
375	
376	  if (auto op = operand.getDefiningOp()) {
377	    if (auto addPtrOp = dyn_cast<triton::AddPtrOp>(op)) {
378	      return visitOperandAddptr(cast<triton::AddPtrOp>(op), state, loc,
379	                                builder);
380	    } else if (auto bitCastOp = dyn_cast<triton::BitcastOp>(op)) {
381	      newSource = operand;
382	    } else if (auto makeTensorOp = dyn_cast<triton::MakeTensorPtrOp>(op)) {
383	      LLVM_DEBUG({
384	        op->emitWarning("Unexpected operand defining operation tts.make_tptr.");
385	      });
386	      return failure();
387	    } else if (auto intToPtrOp = dyn_cast<triton::IntToPtrOp>(op)) {
388	      newSource = operand;
389	    } else {
390	      LLVM_DEBUG({ op->emitWarning("PtrAnalysis: Unexpected operand."); });
391	      return failure();
392	    }
393	  } else {
394	    newSource = operand;
395	  }
396	  auto newOffset = builder.getIndexAttr(0);
397	  state.updatePtrState(newStateInfo, newSizes, newSource, newOffset, loc,
398	                       builder);
399	  return success();
400	}
