402	LogicalResult PtrState::mulState(const PtrState &lhsState,
403	                                 const PtrState &rhsState, Operation *op,
404	                                 OpBuilder &builder) {
405	  auto loc = op->getLoc();
406	
407	  LLVM_DEBUG({
408	    llvm::dbgs() << "----------------------------------------------\n";
409	    llvm::dbgs() << "mulState: " << op << "\n";
410	  });
411	
412	  if (!isEmpty()) {
413	    LLVM_DEBUG({
414	      op->emitError("PtrAnalysis: PtrState should be empty when multiplying");
415	    });
416	    return failure();
417	  }
418	
419	  // neither lhs nor rhs should have source, since multiplying base pointer
420	  // does not make sense
421	  if (lhsState.hasSource() || rhsState.hasSource()) {
422	    LLVM_DEBUG({
423	      op->emitError("PtrAnalysis: do not support base inters in multiplying");
424	    });
425	    return failure();
426	  } else if (!lhsState.isScalar() && !rhsState.isScalar()) {
427	    // do not support both tensors are effectively non-scalar
428	    LLVM_DEBUG({
429	      op->emitError(
430	          "PtrAnalysis: only support multiplying pointer states when one of "
431	          "them represent a scalar");
432	    });
433	    return failure();
434	  }
435	
436	  PtrState const *lhs = &lhsState;
437	  PtrState const *rhs = &rhsState;
438	
439	  if (!rhs->isScalar() && lhs->isScalar()) {
440	    std::swap(lhs, rhs);
441	  }
442	
443	  SmallVector<StateInfo> newStateInfo;
444	  for (auto info : lhs->stateInfo) {
445	    OpFoldResult newStride =
446	        mulOpFoldResult(info.stride, rhs->offset, loc, builder);
447	    newStateInfo.emplace_back(newStride, info.shape, info.dimIndex);
448	  }
449	
450	  auto newOffset =
451	      mulOpFoldResult(lhsState.offset, rhsState.offset, loc, builder);
452	  updatePtrState(newStateInfo, lhs->sizes, lhs->source, newOffset, loc, builder,
453	                 lhs->shouldLinearize);
454	
455	  LLVM_DEBUG({
456	    llvm::dbgs() << "After mulState: \n";
457	    this->dump();
458	    llvm::dbgs() << "----------------------------------------------\n";
459	  });
460	
461	  return success();
462	}
