464	LogicalResult PtrState::subState(const PtrState &lhsState,
465	                                 const PtrState &rhsState, Operation *op,
466	                                 OpBuilder &builder) {
467	  auto loc = op->getLoc();
468	  if (!isEmpty()) {
469	    LLVM_DEBUG({
470	      op->emitError("PtrAnalysis: PtrState should be empty when subtracting");
471	    });
472	    return failure();
473	  }
474	
475	  if (lhsState.hasSource() && rhsState.hasSource()) {
476	    LLVM_DEBUG({
477	      op->emitError(
478	          "PtrAnalysis: do not support both sides have base pointers in sub");
479	    });
480	    return failure();
481	  }
482	
483	  if (!rhsState.isScalar()) {
484	    LLVM_DEBUG({
485	      op->emitError("PtrAnalysis: only support sub when one of "
486	                    "them represents a scalar");
487	    });
488	    return failure();
489	  }
490	
491	  auto newOffset =
492	      subOpFoldResult(lhsState.offset, rhsState.offset, loc, builder);
493	  updatePtrState(lhsState.stateInfo, lhsState.sizes, lhsState.source, newOffset,
494	                 loc, builder, lhsState.shouldLinearize);
495	
496	  return success();
497	}
