499	LogicalResult PtrState::addState(PtrState &lhsState, PtrState &rhsState,
500	                                 Operation *op, OpBuilder &builder) {
501	  auto loc = op->getLoc();
502	
503	  LLVM_DEBUG({
504	    llvm::dbgs() << "----------------------------------------------\n";
505	    llvm::dbgs() << "addState: " << op << "\n";
506	  });
507	
508	  if (!isEmpty()) {
509	    LLVM_DEBUG({
510	      op->emitError("PtrAnalysis: PtrState should be empty when adding");
511	    });
512	    return failure();
513	  }
514	  if (!lhsState.isSameSizeAs(rhsState)) {
515	    LLVM_DEBUG({
516	      op->emitError(
517	          "PtrAnalysis: The original size of the addition should be the same");
518	    });
519	    return failure();
520	  }
521	
522	  SmallVector<StateInfo> newStateInfo;
523	  auto lIt = lhsState.stateInfo.begin();
524	  auto rIt = rhsState.stateInfo.begin();
525	  while (lIt != lhsState.stateInfo.end() && rIt != rhsState.stateInfo.end()) {
526	    if (lIt->dimIndex != rIt->dimIndex) {
527	      auto newInfo = lIt->dimIndex < rIt->dimIndex ? *lIt++ : *rIt++;
528	      newStateInfo.emplace_back(newInfo);
529	      continue;
530	    }
531	    if (!isMultiple(lIt->shape, rIt->shape) &&
532	        !isMultiple(rIt->shape, lIt->shape)) {
533	      LLVM_DEBUG({
534	        llvm::dbgs() << "LHS PtrState: \n";
535	        lhsState.dump();
536	        llvm::dbgs() << "RHS PtrState: \n";
537	        rhsState.dump();
538	        llvm::dbgs() << "----------------------------------------------\n";
539	      });
540	      LLVM_DEBUG({
541	        op->emitError("PtrAnalysis: the add operation have incompatible sizes");
542	      });
543	      return failure();
544	    }
545	
546	    auto newShape = minOpFoldResult(lIt->shape, rIt->shape, loc, builder);
547	    if ((isLess(newShape, lIt->shape) && !isZero(lIt->stride) ||
548	         isLess(newShape, rIt->shape) && !isZero(rIt->stride))) {
549	      LLVM_DEBUG({
550	        llvm::dbgs() << "LHS PtrState: \n";
551	        lhsState.dump();
552	        llvm::dbgs() << "RHS PtrState: \n";
553	        rhsState.dump();
554	        llvm::dbgs() << "----------------------------------------------\n";
555	      });
556	      LLVM_DEBUG({
557	        op->emitError("PtrAnalysis: the add operation have incompatible sizes."
558	                      "Valid dimensions are split.");
559	      });
560	      return failure();
561	    }
562	
563	    auto newStride = addOpFoldResult(lIt->stride, rIt->stride, loc, builder);
564	    newStateInfo.emplace_back(newStride, newShape, lIt->dimIndex);
565	
566	    if (isEqual(lIt->shape, newShape))
567	      ++lIt;
568	    else
569	      lIt->shape = divOpFoldResult(lIt->shape, newShape, loc, builder);
570	    if (isEqual(rIt->shape, newShape))
571	      ++rIt;
572	    else
573	      rIt->shape = divOpFoldResult(rIt->shape, newShape, loc, builder);
574	  }
575	
576	  while (rIt != rhsState.stateInfo.end()) {
577	    newStateInfo.push_back(*rIt++);
578	  }
579	  while (lIt != lhsState.stateInfo.end()) {
580	    newStateInfo.push_back(*lIt++);
581	  }
582	
583	  auto newSource = source = lhsState.source ? lhsState.source : rhsState.source;
584	  auto newOffset =
585	      addOpFoldResult(lhsState.offset, rhsState.offset, loc, builder);
586	  auto newShouldLinearize =
587	      lhsState.shouldLinearize || rhsState.shouldLinearize;
588	  auto newSizes = lhsState.sizes;
589	
590	  updatePtrState(newStateInfo, newSizes, newSource, newOffset, loc, builder,
591	                 newShouldLinearize);
592	
593	  LLVM_DEBUG({
594	    llvm::dbgs() << "After addState: \n";
595	    this->dump();
596	    llvm::dbgs() << "----------------------------------------------\n";
597	  });
598	
599	  return success();
600	}
