602	triton::AddPtrOp PtrState::createAddPtrOp(OpBuilder &builder, Location loc) {
603	  SmallVector<int64_t> tensorSizes;
604	  SmallVector<OpFoldResult> tensorStrides;
605	
606	  auto zeroAttr = builder.getIndexAttr(0);
607	  auto oneAttr = builder.getIndexAttr(1);
608	
609	  for (auto id : permuteIds) {
610	    auto info = stateInfo[id];
611	    if (isZero(info.stride))
612	      continue;
613	    tensorStrides.emplace_back(info.stride);
614	    tensorSizes.emplace_back(getIntAttr(info.shape).value());
615	  }
616	
617	  // load a scalar pointer
618	  if (tensorSizes.empty()) {
619	    Value offsetValue = materializeValue(builder, loc, offset);
620	    if (offsetValue.getType().isIndex()) {
621	      offsetValue = builder.create<arith::IndexCastOp>(
622	          loc, builder.getI32Type(), offsetValue);
623	    }
624	    auto addptrOp = builder.create<triton::AddPtrOp>(loc, source.getType(),
625	                                                     source, offsetValue);
626	    return addptrOp;
627	  }
628	
629	  SmallVector<Value> cachedRange;
630	  auto ptrType = cast<triton::PointerType>(source.getType());
631	  auto ptrTensorType = RankedTensorType::get({tensorSizes}, ptrType);
632	  auto broadCastType =
633	      RankedTensorType::get({tensorSizes}, builder.getI32Type());
634	
635	  if (tensorSizes.size() != tensorStrides.size()) {
636	    LLVM_DEBUG(
637	        {
638	          InFlightDiagnostic diag =
639	              emitError(loc)
640	              << "PtrAnalysis: inconsistent tensor sizes and strides";
641	        });
642	    return nullptr;
643	  }
644	  for (size_t i = 0; i < tensorSizes.size(); ++i) {
645	    // make range
646	    auto indexI32RowType =
647	        RankedTensorType::get({tensorSizes[i]}, builder.getI32Type());
648	    Value makeRangeOp = builder.create<triton::MakeRangeOp>(
649	        loc, indexI32RowType, 0, tensorSizes[i]);
650	
651	    // multiply stride
652	    Value strideValue = materializeValue(builder, loc, tensorStrides[i]);
653	    if (strideValue.getType().isIndex()) {
654	      strideValue = builder.create<arith::IndexCastOp>(
655	          loc, builder.getI32Type(), strideValue);
656	    }
657	    Value splatStride =
658	        builder.create<triton::SplatOp>(loc, indexI32RowType, strideValue);
659	    auto rangeAfterMul =
660	        builder.create<arith::MulIOp>(loc, makeRangeOp, splatStride);
661	
662	    // reshape
663	    Value expandedValue = rangeAfterMul;
664	    for (size_t j = 0; j < tensorSizes.size(); ++j) {
665	      if (j == i)
666	        continue;
667	      expandedValue =
668	          builder.create<triton::ExpandDimsOp>(loc, expandedValue, j);
669	    }
670	
671	    // broadcast
672	    auto broadcastValue =
673	        builder.create<triton::BroadcastOp>(loc, broadCastType, expandedValue);
674	    cachedRange.push_back(broadcastValue);
675	  }
676	
677	  // combine the cachedRange
678	  Value rangeAfterCombine = cachedRange[0];
679	  for (size_t i = 1; i < cachedRange.size(); ++i) {
680	    rangeAfterCombine =
681	        builder.create<arith::AddIOp>(loc, rangeAfterCombine, cachedRange[i]);
682	  }
683	
684	  // addOffset
685	  Value addValue = materializeValue(builder, loc, offset);
686	  if (addValue.getType().isIndex()) {
687	    addValue =
688	        builder.create<arith::IndexCastOp>(loc, builder.getI32Type(), addValue);
689	  }
690	  Value splatOffset =
691	      builder.create<triton::SplatOp>(loc, broadCastType, addValue);
692	  auto rangeAfterAdd =
693	      builder.create<arith::AddIOp>(loc, rangeAfterCombine, splatOffset);
694	
695	  // addPtr
696	  Value splatPtr = builder.create<triton::SplatOp>(loc, ptrTensorType, source);
697	  auto addptrOp = builder.create<triton::AddPtrOp>(loc, ptrTensorType, splatPtr,
698	                                                   rangeAfterAdd);
699	  return addptrOp;
700	}
701	
702	triton::MakeTensorPtrOp PtrState::createMakeTensorPtrOp(OpBuilder &builder,
703	                                                        Location loc) {
704	  SmallVector<Value> newShape;
705	  SmallVector<Value> newStrides;
706	  SmallVector<Value> newOffsets;
707	  SmallVector<int32_t> newBlkShape;
708	  SmallVector<int32_t> newOrder; // must be int32_t for MakeTensorPtrOp builder
709	
710	  const size_t rank = order.size();
711	  if (rank == 0) {
712	    emitError(loc) << "PtrAnalysis: empty order in createMakeTensorPtrOp";
713	    return nullptr;
714	  }
715	
716	  // iterate reversed safely: i = rank-1, ..., 0
717	  for (size_t i = rank; i-- > 0;) {
718	    size_t dim = order[i];
719	
720	    if (dim >= stateInfo.size() || dim >= dimOffsets.size() ||
721	        dim >= sizes.size()) {
722	      emitError(loc)
723	          << "PtrAnalysis: invalid dim index in createMakeTensorPtrOp";
724	      return nullptr;
725	    }
726	
727	    auto info = stateInfo[dim];
728	
729	    newShape.push_back(materializeValue(builder, loc, info.shape));
730	    newStrides.push_back(materializeValue(builder, loc, info.stride));
731	    newOffsets.push_back(materializeValue(builder, loc, dimOffsets[dim]));
732	
733	    auto blkSzOpt = getIntAttr(sizes[dim]);
734	    if (!blkSzOpt.has_value()) {
735	      emitError(loc) << "PtrAnalysis: dynamic block_shape is not supported for "
736	                        "tt.make_tensor_ptr";
737	      return nullptr;
738	    }
739	    newBlkShape.push_back(static_cast<int32_t>(blkSzOpt.value()));
740	    newOrder.push_back(static_cast<int32_t>(i));
741	  }
742	
743	  return builder.create<triton::MakeTensorPtrOp>(
744	      loc, source, ValueRange(newShape), ValueRange(newStrides),
745	      ValueRange(newOffsets), newBlkShape, newOrder);
746	}
