785	LogicalResult PtrAnalysis::visitOperandMakeRange(triton::MakeRangeOp rangeOp,
786	                                                 PtrState &state, Location loc,
787	                                                 OpBuilder &builder) {
788	  if (!state.isEmpty()) {
789	    LLVM_DEBUG({
790	      rangeOp.emitError(
791	          "PtrAnalysis: PtrState should be empty when visiting make_range");
792	    });
793	    return failure();
794	  }
795	
796	  auto shape = cast<ShapedType>(rangeOp.getType()).getShape();
797	
798	  auto start = rangeOp.getStart();
799	  auto end = rangeOp.getEnd();
800	  auto stride = (end - start + shape[0] - 1) / shape[0];
801	  if (stride != 1) {
802	    LLVM_DEBUG({
803	      rangeOp.emitError(
804	          "PtrAnalysis: make_range op with stride != 1 is not supported");
805	    });
806	    return failure();
807	  }
808	
809	  auto infoStride = builder.getIndexAttr(stride);
810	  auto size = builder.getIndexAttr(shape[0]);
811	  auto offset = builder.getIndexAttr(start);
812	
813	  SmallVector<StateInfo> stateInfo;
814	  SmallVector<OpFoldResult> sizes;
815	  stateInfo.emplace_back(infoStride, size);
816	  sizes.emplace_back(size);
817	
818	  state.updatePtrState(stateInfo, sizes, nullptr, offset, loc, builder);
819	  return success();
820	}
821	
822	LogicalResult
823	PtrAnalysis::visitOperandBroadcast(triton::BroadcastOp broadcastOp,
824	                                   PtrState &state, const Location loc,
825	                                   OpBuilder &builder) {
826	  if (!state.isEmpty()) {
827	    LLVM_DEBUG({
828	      broadcastOp.emitError(
829	          "PtrAnalysis: PtrState should be empty when visiting broadcast");
830	    });
831	    return failure();
832	  }
833	
834	  auto src = broadcastOp.getSrc();
835	  auto dst = broadcastOp.getResult();
836	  if (!isa<ShapedType>(dst.getType())) {
837	    LLVM_DEBUG({
838	      broadcastOp.emitRemark(
839	          "PtrAnalysis: broadcast dst should be a shaped type");
840	    });
841	    return failure();
842	  }
843	
844	  auto srcShape = cast<ShapedType>(src.getType()).getShape();
845	  auto dstShape = cast<ShapedType>(dst.getType()).getShape();
846	  if (srcShape.size() != dstShape.size()) {
847	    LLVM_DEBUG({
848	      broadcastOp.emitRemark(
849	          "PtrAnalysis: broadcast src and dst should have the same rank");
850	    });
851	    return failure();
852	  }
853	  if (visitOperand(src, state, loc, builder).failed()) {
854	    return failure();
855	  }
856	
857	  if (state.sizes.size() != dstShape.size()) {
858	    llvm::dbgs() << broadcastOp << "\n";
859	    state.dump();
860	    llvm::dbgs() << "dst.size = " << dstShape.size() << "\n";
861	    for (auto x : dstShape)
862	      llvm::dbgs() << x << ", ";
863	    llvm::dbgs() << "\n";
864	  }
865	
866	  SmallVector<StateInfo> newStateInfo(state.stateInfo);
867	  SmallVector<OpFoldResult> newSizes;
868	  if (srcShape.size() != dstShape.size()) {
869	    LLVM_DEBUG({
870	      broadcastOp.emitRemark(
871	          "PtrAnalysis: unexpected state info size in broadcast");
872	    });
873	    return failure();
874	  }
875	  for (size_t i = 0; i < dstShape.size(); ++i) {
876	    newSizes.emplace_back(builder.getIndexAttr(dstShape[i]));
877	    if (srcShape[i] == dstShape[i]) {
878	      continue;
879	    } else if (srcShape[i] < dstShape[i] && srcShape[i] == 1) {
880	      for (auto &info : newStateInfo) {
881	        if (info.dimIndex != i)
882	          continue;
883	        info.shape = builder.getIndexAttr(dstShape[i]);
884	      }
885	    } else {
886	      LLVM_DEBUG({
887	        broadcastOp.emitRemark("unexpected dimensions used in broadcast");
888	      });
889	      return failure();
890	    }
891	  }
892	  state.updatePtrState(newStateInfo, newSizes, state.source, state.offset, loc,
893	                       builder, state.shouldLinearize);
894	  return success();
895	}
