897	LogicalResult PtrAnalysis::visitOperandSplat(triton::SplatOp splatOp,
898	                                             PtrState &state,
899	                                             const Location loc,
900	                                             OpBuilder &builder) {
901	  if (!state.isEmpty()) {
902	    LLVM_DEBUG({
903	      splatOp.emitError(
904	          "PtrAnalysis: PtrState should be empty when visiting splat");
905	    });
906	    return failure();
907	  }
908	
909	  LLVM_DEBUG({
910	    llvm::dbgs() << "----------------------------------------------\n";
911	    llvm::dbgs() << "Visit SPLAT operation: " << splatOp << "\n";
912	  });
913	
914	  auto src = splatOp.getSrc();
915	  auto dst = splatOp.getResult();
916	  auto dstShape = cast<ShapedType>(dst.getType()).getShape();
917	
918	  if (visitOperand(src, state, loc, builder).failed()) {
919	    return failure();
920	  }
921	
922	  LLVM_DEBUG({
923	    llvm::dbgs() << "splat ptrState: \n";
924	    state.dump();
925	    llvm::dbgs() << "----------------------------------------------\n";
926	  });
927	
928	  if (!state.isScalar()) {
929	    LLVM_DEBUG(
930	        { splatOp.emitRemark("PtrAnalysis: splat source should be scalar"); });
931	    return failure();
932	  }
933	
934	  SmallVector<StateInfo> newStateInfo;
935	  SmallVector<OpFoldResult> newSizes;
936	  auto zeroAttr = builder.getIndexAttr(0);
937	  if (isa<IntegerType, IndexType, triton::PointerType>(src.getType())) {
938	    for (size_t i = 0; i < dstShape.size(); ++i) {
939	      auto currentSize = builder.getIndexAttr(dstShape[i]);
940	      newSizes.emplace_back(currentSize);
941	      newStateInfo.emplace_back(zeroAttr, currentSize, i);
942	    }
943	  } else {
944	    LLVM_DEBUG(
945	        { splatOp.emitRemark("PtrAnalysis: unsupported splat pattern"); });
946	    return failure();
947	  }
948	  state.updatePtrState(newStateInfo, newSizes, state.source, state.offset, loc,
949	                       builder, state.shouldLinearize);
950	
951	  LLVM_DEBUG({
952	    llvm::dbgs() << "After SPLAT ptrState: \n";
953	    state.dump();
954	    llvm::dbgs() << "----------------------------------------------\n";
955	  });
956	  return success();
957	}
