959	LogicalResult
960	PtrAnalysis::visitOperandExpandDims(triton::ExpandDimsOp expandDimsOp,
961	                                    PtrState &state, const Location loc,
962	                                    OpBuilder &builder) {
963	  if (!state.isEmpty()) {
964	    LLVM_DEBUG({
965	      expandDimsOp.emitError(
966	          "PtrAnalysis: PtrState should be empty when visiting expand_dims");
967	    });
968	    return failure();
969	  }
970	
971	  if (visitOperand(expandDimsOp.getSrc(), state, loc, builder).failed()) {
972	    return failure();
973	  }
974	
975	  auto dstShape =
976	      cast<ShapedType>(expandDimsOp.getResult().getType()).getShape();
977	  auto axis = expandDimsOp.getAxis();
978	
979	  SmallVector<StateInfo> newStateInfo(state.stateInfo);
980	  SmallVector<OpFoldResult> newSizes(state.sizes);
981	  size_t insertPos = 0;
982	  for (auto &info : newStateInfo) {
983	    if (info.dimIndex >= axis)
984	      ++info.dimIndex;
985	    if (info.dimIndex < axis)
986	      ++insertPos;
987	  }
988	  auto zeroAttr = builder.getIndexAttr(0);
989	  auto oneAttr = builder.getIndexAttr(1);
990	  StateInfo insertInfo(zeroAttr, oneAttr, axis);
991	
992	  newStateInfo.insert(newStateInfo.begin() + insertPos, insertInfo);
993	  newSizes.insert(newSizes.begin() + axis, oneAttr);
994	
995	  state.updatePtrState(newStateInfo, newSizes, state.source, state.offset, loc,
996	                       builder, state.shouldLinearize);
997	  return success();
998	}
