1000	LogicalResult PtrAnalysis::visitOperandConstSplat(arith::ConstantOp op,
1001	                                                  PtrState &state,
1002	                                                  const Location loc,
1003	                                                  OpBuilder &builder) {
1004	  if (!state.isEmpty()) {
1005	    LLVM_DEBUG({
1006	      op->emitError(
1007	          "PtrAnalysis: PtrState should be empty when visiting const_splat");
1008	    });
1009	    return failure();
1010	  }
1011	
1012	  auto attr = cast<DenseElementsAttr>(op.getValue());
1013	  auto elementType = attr.getElementType();
1014	  if (!attr.isSplat() || !isa<IntegerType>(elementType)) {
1015	    LLVM_DEBUG(
1016	        { op->emitError("PtrAnalysis: only support splat integer constant"); });
1017	    return failure();
1018	  }
1019	
1020	  auto value = attr.getValues<IntegerAttr>()[0].getValue();
1021	  auto constAttr = builder.getIndexAttr(value.getSExtValue());
1022	
1023	  auto resultShape = cast<ShapedType>(op.getResult().getType()).getShape();
1024	
1025	  SmallVector<OpFoldResult> sizes;
1026	  SmallVector<StateInfo> stateInfo;
1027	  auto defaultAttr = builder.getIndexAttr(0);
1028	
1029	  for (auto [i, shape] : llvm::enumerate(resultShape)) {
1030	    auto shapeAttr = builder.getIndexAttr(shape);
1031	    sizes.emplace_back(shapeAttr);
1032	    stateInfo.emplace_back(defaultAttr, shapeAttr, i);
1033	  }
1034	
1035	  state.updatePtrState(stateInfo, sizes, nullptr, constAttr, loc, builder);
1036	  return success();
1037	}
