1057	
1058	LogicalResult PtrAnalysis::visitOperandRem(arith::RemSIOp remOp,
1059	                                           PtrState &state, const Location loc,
1060	                                           OpBuilder &builder) {
1061	  if (!state.isEmpty()) {
1062	    LLVM_DEBUG({
1063	      remOp.emitError(
1064	          "PtrAnalysis: PtrState should be empty when visiting remsi");
1065	    });
1066	    return failure();
1067	  }
1068	  LLVM_DEBUG({
1069	    llvm::dbgs() << "before VisitRemOperands \n";
1070	    state.dump();
1071	  });
1072	
1073	  PtrState rhsState;
1074	  if (visitOperand(remOp.getRhs(), rhsState, loc, builder).failed()) {
1075	    return failure();
1076	  }
1077	
1078	  if (!rhsState.isScalar() || rhsState.hasSource()) {
1079	    LLVM_DEBUG({
1080	      remOp.emitRemark("PtrAnalysis: only support cases when rhs of remainder "
1081	                       "contains scalar");
1082	    });
1083	    return failure();
1084	  }
1085	
1086	  if (visitOperand(remOp.getLhs(), state, loc, builder).failed()) {
1087	    return failure();
1088	  }
1089	
1090	  bool hasAnnotation = optimizeDynamicOffset;
1091	
1092	  auto zeroAttr = builder.getIndexAttr(0);
1093	  auto oneAttr = builder.getIndexAttr(1);
1094	  auto divisorAttr = rhsState.offset;
1095	
1096	  auto staticOffset = getIntAttr(state.offset);
1097	  if ((!staticOffset.has_value() || !isMultiple(state.offset, divisorAttr)) &&
1098	      !hasAnnotation) {
1099	    LLVM_DEBUG({
1100	      remOp.emitRemark(
1101	          "PtrAnalysis: dynamic offset before REMSI, adding annotation");
1102	    });
1103	    return failure();
1104	  }
1105	
1106	  if (!getIntAttr(divisorAttr).has_value()) {
1107	    LLVM_DEBUG({
1108	      remOp.emitError("PtrAnalysis: do not support dynamix divisor in REMSI.");
1109	    });
1110	    return failure();
1111	  }
1112	
1113	  SmallVector<StateInfo> newStateInfo;
1114	  for (auto info : state.stateInfo) {
1115	    if (!getIntAttr(info.stride).has_value()) {
1116	      LLVM_DEBUG({
1117	        remOp.emitError(
1118	            "PtrAnalysis: do not support dynamix stride before REMSI.");
1119	      });
1120	      return failure();
1121	    }
1122	
1123	    if (!isMultiple(divisorAttr, info.shape) &&
1124	        !isMultiple(info.shape, divisorAttr)) {
1125	      LLVM_DEBUG({
1126	        remOp.emitError(
1127	            "PtrAnalysis: do not support dynamix stride before REMSI.");
1128	      });
1129	    }
1130	
1131	    if (isMultiple(info.stride, divisorAttr)) {
1132	      newStateInfo.emplace_back(zeroAttr, info.shape, info.dimIndex);
1133	    } else if (isMultiple(divisorAttr, info.stride)) {
1134	      auto contiguousSize =
1135	          divOpFoldResult(divisorAttr, info.stride, loc, builder);
1136	      contiguousSize =
1137	          minOpFoldResult(contiguousSize, info.shape, loc, builder);
1138	      auto nonContiguousSize =
1139	          divOpFoldResult(info.shape, contiguousSize, loc, builder);
1140	
1141	      auto staticNonContiguousSize = getIntAttr(nonContiguousSize);
1142	      if (!staticNonContiguousSize.has_value()) {
1143	        LLVM_DEBUG({
1144	          remOp.emitError(
1145	              "PtrAnalysis: do not support dynamix size before REMSI.");
1146	        });
1147	        return failure();
1148	      }
1149	
1150	      if (staticNonContiguousSize.value() > 1)
1151	        newStateInfo.emplace_back(zeroAttr, nonContiguousSize, info.dimIndex);
1152	
1153	      newStateInfo.emplace_back(info.stride, contiguousSize, info.dimIndex);
1154	    } else {
1155	      LLVM_DEBUG({
1156	        remOp.emitError("PtrAnalysis: stride that are not divisible by REMSI "
1157	                        "are not allowed "
1158	                        "to precede REMSI");
1159	      });
1160	      return failure();
1161	    }
1162	  }
1163	
1164	  auto newOffset = remOpFoldResult(state.offset, divisorAttr, loc, builder);
1165	  state.updatePtrState(newStateInfo, state.sizes, state.source, newOffset, loc,
1166	                       builder, true);
1167	
1168	  LLVM_DEBUG({
1169	    llvm::dbgs() << "after VisitRemOperands \n";
1170	    state.dump();
1171	  });
1172	
1173	  return success();
1174	}
1175	
1176	LogicalResult PtrAnalysis::visitOperandDiv(arith::DivSIOp divOp,
1177	                                           PtrState &state, const Location loc,
1178	                                           OpBuilder &builder) {
1179	  if (!state.isEmpty()) {
1180	    LLVM_DEBUG({
1181	      divOp.emitError(
1182	          "PtrAnalysis: PtrState should be empty when visiting divsi");
1183	    });
1184	    return failure();
1185	  }
1186	  LLVM_DEBUG({
1187	    llvm::dbgs() << "----------------------------------------------\n";
1188	    llvm::dbgs() << "Visit DIVSI operation: " << divOp << "\n";
1189	  });
1190	
1191	  PtrState rhsState;
1192	  if (visitOperand(divOp.getRhs(), rhsState, loc, builder).failed()) {
1193	    return failure();
1194	  }
1195	
1196	  if (!rhsState.isScalar() || rhsState.hasSource()) {
1197	    LLVM_DEBUG({
1198	      divOp.emitRemark("PtrAnalysis: only support cases when rhs of remainder "
1199	                       "contains scalar");
1200	    });
1201	    return failure();
1202	  }
1203	
1204	  if (visitOperand(divOp.getLhs(), state, loc, builder).failed()) {
1205	    return failure();
1206	  }
1207	
1208	  bool hasAnnotation = optimizeDynamicOffset;
1209	
1210	  auto staticMultipleOf = extractDivisibilityFromOpFoldResult(state.offset);
1211	  if (!hasAnnotation && staticMultipleOf.has_value()) {
1212	    auto attr = builder.getIndexAttr(staticMultipleOf.value());
1213	    hasAnnotation = isMultiple(attr, rhsState.offset);
1214	  }
1215	
1216	  // add divState
1217	  auto zeroAttr = builder.getIndexAttr(0);
1218	  auto oneAttr = builder.getIndexAttr(1);
1219	  auto divisorAttr = rhsState.offset;
1220	
1221	  auto staticOffset = getIntAttr(state.offset);
1222	  if ((!staticOffset.has_value() || !isMultiple(state.offset, divisorAttr)) &&
1223	      !hasAnnotation) {
1224	    LLVM_DEBUG({
1225	      divOp.emitRemark(
1226	          "PtrAnalysis: dynamic offset before DIVSI, adding annotation");
1227	    });
1228	    return failure();
1229	  }
1230	
1231	  if (!getIntAttr(divisorAttr).has_value()) {
1232	    LLVM_DEBUG({
1233	      divOp.emitError("PtrAnalysis: do not support dynamix divisor in DIVSI.");
1234	    });
1235	    return failure();
1236	  }
1237	
1238	  SmallVector<StateInfo> newStateInfo;
1239	  for (auto info : state.stateInfo) {
1240	    auto staticStride = getIntAttr(info.stride);
1241	    if (!staticStride.has_value()) {
1242	      LLVM_DEBUG({
1243	        divOp.emitError(
1244	            "PtrAnalysis: do not support dynamix stride before DIVSI.");
1245	      });
1246	      return failure();
1247	    }
1248	
1249	    if (!isMultiple(divisorAttr, info.shape) &&
1250	        !isMultiple(info.shape, divisorAttr)) {
1251	      LLVM_DEBUG({
1252	        divOp.emitError(
1253	            "PtrAnalysis: do not support dynamix stride before DivSI.");
1254	      });
1255	    }
1256	
1257	    if (isMultiple(info.stride, divisorAttr)) {
1258	      auto newStride = divOpFoldResult(info.stride, divisorAttr, loc, builder);
1259	      newStateInfo.emplace_back(newStride, info.shape, info.dimIndex);
1260	    } else if (isMultiple(divisorAttr, info.stride)) {
1261	      auto nonContiguousSize =
1262	          divOpFoldResult(divisorAttr, info.stride, loc, builder);
1263	      nonContiguousSize =
1264	          minOpFoldResult(nonContiguousSize, info.shape, loc, builder);
1265	      auto contiguousSize =
1266	          divOpFoldResult(info.shape, nonContiguousSize, loc, builder);
1267	
1268	      auto staticContiguousSize = getIntAttr(contiguousSize);
1269	      if (!staticContiguousSize.has_value()) {
1270	        LLVM_DEBUG({
1271	          divOp.emitError(
1272	              "PtrAnalysis: do not support dynamix size before DIVSI.");
1273	        });
1274	        return failure();
1275	      }
1276	
1277	      if (staticContiguousSize.value() != 0)
1278	        newStateInfo.emplace_back(oneAttr, contiguousSize, info.dimIndex);
1279	
1280	      newStateInfo.emplace_back(zeroAttr, nonContiguousSize, info.dimIndex);
1281	    } else {
1282	      LLVM_DEBUG({
1283	        divOp.emitError("PtrAnalysis: stride that are not divisible by DIVSI "
1284	                        "are not allowed "
1285	                        "to precede DIVSI");
1286	      });
1287	      return failure();
1288	    }
1289	  }
1290	
1291	  auto newOffset = divOpFoldResult(state.offset, divisorAttr, loc, builder);
1292	  state.updatePtrState(newStateInfo, state.sizes, state.source, newOffset, loc,
1293	                       builder, true);
1294	
1295	  LLVM_DEBUG({
1296	    llvm::dbgs() << "after VisitDivOperands \n";
1297	    state.dump();
1298	  });
1299	  return success();
1300	}
