1302	LogicalResult PtrAnalysis::visitOperandAdd(arith::AddIOp addOp, PtrState &state,
1303	                                           const Location loc,
1304	                                           OpBuilder &builder) {
1305	  PtrState lhsState;
1306	  if (visitOperand(addOp.getLhs(), lhsState, loc, builder).failed()) {
1307	    return failure();
1308	  }
1309	
1310	  PtrState rhsState;
1311	  if (visitOperand(addOp.getRhs(), rhsState, loc, builder).failed())
1312	    return failure();
1313	  return state.addState(lhsState, rhsState, addOp, builder);
