1315	
1316	LogicalResult PtrAnalysis::visitOperand(Value operand, PtrState &state,
1317	                                        const Location loc,
1318	                                        OpBuilder &builder) {
1319	  if (knownPtrs.find(operand) != knownPtrs.end()) {
1320	    state = knownPtrs.lookup(operand);
1321	    return success();
1322	  }
1323	
1324	  if (operandIsScalar(operand)) {
1325	    return initStateByScalar(operand, state, loc, builder);
1326	  }
1327	
1328	  if (isa<triton::PointerType>(operand.getType())) {
1329	    return initStateByPointer(operand, state, loc, builder);
1330	  }
1331	
1332	  if (auto op = operand.getDefiningOp<arith::AddIOp>()) {
1333	    return visitOperandAdd(op, state, loc, builder);
1334	  } else if (auto op = operand.getDefiningOp<arith::MulIOp>()) {
1335	    return visitOperandMul(op, state, loc, builder);
1336	  } else if (auto op = operand.getDefiningOp<arith::SubIOp>()) {
1337	    return visitOperandSub(op, state, loc, builder);
1338	  } else if (auto op = operand.getDefiningOp<triton::MakeRangeOp>()) {
1339	    return visitOperandMakeRange(op, state, loc, builder);
1340	  } else if (auto op = operand.getDefiningOp<triton::BroadcastOp>()) {
1341	    return visitOperandBroadcast(op, state, loc, builder);
1342	  } else if (auto op = operand.getDefiningOp<triton::SplatOp>()) {
1343	    return visitOperandSplat(op, state, loc, builder);
1344	  } else if (auto op = operand.getDefiningOp<triton::ExpandDimsOp>()) {
1345	    return visitOperandExpandDims(op, state, loc, builder);
1346	  } else if (auto op = operand.getDefiningOp<triton::AddPtrOp>()) {
1347	    return visitOperandAddptr(op, state, loc, builder);
1348	  } else if (auto op = operand.getDefiningOp<arith::ConstantOp>()) {
1349	    return visitOperandConstSplat(op, state, loc, builder);
1350	  } else if (auto op = operand.getDefiningOp<arith::RemSIOp>()) {
1351	    return visitOperandRem(op, state, loc, builder);
1352	  } else if (auto op = operand.getDefiningOp<arith::DivSIOp>()) {
1353	    return visitOperandDiv(op, state, loc, builder);
1354	  } else if (auto op = operand.getDefiningOp<arith::ExtSIOp>()) {
1355	    return visitOperandExtSI(op, state, loc, builder);
1356	  } else if (auto op = operand.getDefiningOp<triton::LoadOp>()) {
1357	    LLVM_DEBUG({
1358	      op.emitRemark("TritonToStructured: Invalid dynamic offset"
1359	                    "The load operation's offset cannot be derived from "
1360	                    "another load result.");
1361	    });
1362	    return failure();
1363	  } else if (auto op = operand.getDefiningOp<arith::FPToSIOp>()) {
1364	    LLVM_DEBUG({
1365	      op.emitWarning("IllegalTypeConversionInAddressCalculation"
1366	                     "float-to-int precision conversion is not supported "
1367	                     "during address computation.");
1368	      llvm::dbgs() << "Operand: \n";
1369	      operand.dump();
1370	      llvm::dbgs() << "----------------------------------------------\n";
1371	    });
1372	    return failure();
1373	  } else if (!operand.getDefiningOp()) {
1374	    if (!knownPtrs.contains(operand)) {
1375	      LLVM_DEBUG({
1376	        llvm::dbgs() << "TritonToStructured: Pointer analysis is not supported "
1377	                        "for input parameters\n";
1378	      });
1379	      return failure();
1380	    }
1381	
1382	    // This operand must be an iter-arg of an inner-loop in a multiple-level
1383	    // nested loop, which means its PtrState must have already been populated
1384	    // during rewriteForOp of the parent loop.
1385	    state = knownPtrs[operand];
1386	    return success();
1387	  } else {
1388	    auto op = operand.getDefiningOp();
1389	    LLVM_DEBUG({
1390	      op->emitWarning("TritonToStructured: encountered addptr operand produced "
1391	                      "by an unsupported operation");
1392	      llvm::dbgs() << "Operand: \n";
1393	      operand.dump();
1394	      llvm::dbgs() << "----------------------------------------------\n";
1395	    });
1396	    return failure();
1397	  }
1398	  return success();
1399	}
1400	
1401	LogicalResult PtrAnalysis::rewriteAddptrOp(triton::AddPtrOp op) {
1402	  OpBuilder builder(op);
1403	  auto loc = op.getLoc();
1404	
1405	  PtrState state;
1406	  if (visitOperandAddptr(op, state, op.getLoc(), builder).failed()) {
1407	    return failure();
1408	  }
1409	
1410	  auto maketptrOp = state.createAddPtrOp(builder, op.getLoc());
1411	  knownPtrs[op.getResult()] = state;
1412	  ptrMap.map(op.getResult(), maketptrOp.getResult());
1413	
1414	  return success();
1415	}
1416	
1417	void PtrState::analyzePermute() {
1418	  const size_t n = stateInfo.size();
1419	  generateOriginPermuteIds();
1420	
1421	  if (n <= 1)
1422	    return;
1423	
1424	  // ============================================================
1425	  // === 1. make_tensor_ptr (block ptr): order-based ===
1426	  // Rule: permute if order is NOT canonical (i.e. strictly decreasing,
1427	  // representing inner-to-outer memory layout priority, e.g. [n-1, ..., 0])
1428	  //
1429	  // NOTE: order describes memory layout priority, not axis permutation.
1430	  // Do NOT translate order into permuteIds.
1431	  // ============================================================
1432	  if (isBlockPtr()) {
1433	    for (size_t i = 0; i + 1 < n; ++i) {
1434	      if (order[i] <= order[i + 1]) {
1435	        isPermuted = true;
1436	        break;
1437	      }
1438	    }
1439	    return;
1440	  }
1441	
1442	  // ============================================================
1443	  // === 2. addptr: stride-based permuteIds + contiguous-axis ===
1444	  // Rule: permute if contiguous axes increased
1445	  //
1446	  // analyze constraints: must have at least one static stride
1447	  // ============================================================
1448	  bool hasStatic = false;
1449	  for (auto &s : stateInfo) {
1450	    if (getIntAttr(s.stride).has_value()) {
1451	      hasStatic = true;
1452	      break;
1453	    }
1454	  }
1455	  if (!hasStatic) {
1456	    return;
1457	  }
1458	  auto isIdentity = [&](ArrayRef<size_t> perm) -> bool {
1459	    for (size_t i = 0; i < perm.size(); ++i)
1460	      if (perm[i] != i)
1461	        return false;
1462	    return true;
1463	  };
1464	
1465	  std::stable_sort(permuteIds.begin(), permuteIds.end(),
1466	                   [&](size_t a, size_t b) {
1467	                     return isGreater(stateInfo[a].stride, stateInfo[b].stride);
1468	                   });
1469	
1470	  // If already in canonical axis order, do not permute.
1471	  if (isIdentity(permuteIds)) {
1472	    return;
1473	  }
1474	
1475	  // Tail axis must be physically contiguous (stride == 1),
1476	  // otherwise addptr-based permutation is invalid.
1477	  auto tailStride = getIntAttr(stateInfo[permuteIds.back()].stride);
1478	  if (!tailStride.has_value() || tailStride.value() != 1) {
1479	    generateOriginPermuteIds();
1480	    return;
1481	  }
1482	
1483	  // Compute new contiguous axes count using the permuted stateInfo.
1484	  SmallVector<StateInfo> newStateInfo;
1485	  newStateInfo.reserve(n);
1486	  for (size_t id : permuteIds) {
1487	    newStateInfo.push_back(stateInfo[id]);
1488	  }
1489	  const size_t oldContig = countContiguousAxes(stateInfo);
1490	  const size_t newContig = countContiguousAxes(newStateInfo);
1491	  LLVM_DEBUG({
1492	    llvm::dbgs() << "----------------------------------------------\n";
1493	    llvm::dbgs() << "after analyzePermute:\n"
1494	                 << "oldContig: " << oldContig << "\n"
1495	                 << "newContig: " << newContig << "\n";
1496	    dump();
1497	  });
1498	  // only permute if contiguous axes increased
1499	  if (newContig > oldContig) {
1500	    isPermuted = true;
1501	    return;
1502	  }
1503	
1504	  // otherwise: no permute
1505	  generateOriginPermuteIds();
1506	}
1507	
1508	std::optional<int32_t>
1509	extractDivisibilityFromOpFoldResult(mlir::OpFoldResult ofr) {
1510	  auto value = dyn_cast<mlir::Value>(ofr);
1511	  if (!value) {
1512	    return std::nullopt;
1513	  }
1514	  auto defOp = value.getDefiningOp();
1515	  if (!defOp) {
1516	    return std::nullopt;
1517	  }
1518	
1519	  auto divisibilityAttr = defOp->getAttr("tt.divisibility");
1520	  if (!divisibilityAttr) {
1521	    return std::nullopt;
1522	  }
1523	
1524	  auto denseAttr = dyn_cast<mlir::DenseIntElementsAttr>(divisibilityAttr);
1525	  if (!denseAttr || denseAttr.empty()) {
1526	    return std::nullopt;
1527	  }
1528	
1529	  return denseAttr.getValues<int32_t>()[0];
1530	}
1531	
1532	void PtrState::generateOriginPermuteIds() {
1533	  permuteIds.clear();
1534	  isPermuted = false;
1535	  for (size_t i = 0; i < stateInfo.size(); ++i) {
1536	    permuteIds.emplace_back(i);
1537	  }
1538	  return;
1539	}
1540	
1541	// Formula of "contiguous axes"
1542	// - axis i is contiguous if stride[i] == product(shape[0..i-1]).
1543	// We only prove contiguity from the rightmost axis outward.
1544	// Rules implemented
1545	// - Start from the rightmost axis. It is contiguous only if stride == 1
1546	// (static).
1547	// - Then move left; expectedStride multiplies by the static shape of the axis
1548	// to the right.
1549	// - If we encounter any dynamic stride or dynamic shape needed for
1550	// expectedStride,
1551	//   stop (cannot prove further) and return the count accumulated so far.
1552	// Examples
1553	//  - shape=[2,3,4,5], stride=[A,B,2,C] => rightmost stride is dynamic =>
1554	//  count=0
1555	//  - shape=[2,3,4,5], stride=[A,B,C,1] => rightmost stride=1 => count=1
1556	//  - shape=[2,3,4,5], stride=[60,20,5,1] => count=4
1557	size_t PtrState::countContiguousAxes(SmallVector<StateInfo> stateInfo) const {
1558	  if (stateInfo.empty())
1559	    return 0;
1560	  int64_t expected = 1;
1561	  size_t cnt = 0;
1562	  // iterate reversed safely: i = stateInfo.size()-1, ..., 0
1563	  for (size_t i = stateInfo.size(); i-- > 0;) {
1564	    auto stride = getIntAttr(stateInfo[i].stride);
1565	    if (!stride.has_value())
1566	      break;
1567	    if (stride.value() != expected)
1568	      break;
1569	    ++cnt;
1570	    // Update expected for the next (outer) axis: expected *= shape[i]
1571	    auto shape = getIntAttr(stateInfo[i].shape);
1572	    if (!shape.has_value())
1573	      break;
1574	    expected *= shape.value();
1575	  }
1576	  return cnt;
1577	}
1578	} // namespace TritonToStructured
