78	LogicalResult LoadConverter::matchAndRewrite(triton::LoadOp op,
79	                                             PatternRewriter &rewriter) const {
80	  auto loc = op.getLoc();
81	  auto oldPtr = op.getPtr();
82	  auto oldMask = op.getMask();
83	  auto oldOther = op.getOther();
84	
85	  MemOpTransformer tf(MemOpTransformer::MemType::load, optimizeDynamicOffset);
86	
87	  auto newPtr = tf.createNewPtr(oldPtr, loc, rewriter);
88	  auto newMask = tf.createNewMask(oldMask, loc, rewriter);
89	  auto newOther = tf.createNewOther(oldOther, loc, rewriter);
90	
91	  if (!tf.ptrState.shouldLinearize) {
92	    // no need to rewrite
93	    return failure();
94	  }
95	
96	  if (!newPtr) {
97	    LLVM_DEBUG({
98	      InFlightDiagnostic diag =
99	          emitWarning(loc) << "PtrAnalysis: failed to analyze load pointer.";
100	    });
101	    return failure();
102	  }
103	
104	  if (!enableMaskFallbackConversion && oldMask && !newMask) {
105	    LLVM_DEBUG({
106	      InFlightDiagnostic diag = emitWarning(loc)
107	                                << "MaskAnalysis: failed to analyze load mask.";
108	    });
109	    return failure();
110	  }
111	
112	  auto loadOp = rewriter.create<triton::LoadOp>(loc, newPtr, newMask, newOther,
113	                                                op.getCache(), op.getEvict(),
114	                                                op.getIsVolatile());
115	
116	  // insert implicit ops
117	  auto broadCastResult =
118	      tf.materializeImplicitBroadcast(loadOp.getResult(), loc, rewriter);
119	  auto permuteResult =
120	      tf.materializeImplicitPermute(broadCastResult, loc, rewriter);
121	  auto reshapeResult =
122	      tf.materializeImplicitReshape(permuteResult, loc, rewriter);
123	  auto selectResult = tf.materializeImplicitSelect(reshapeResult, oldMask,
124	                                                   oldOther, loc, rewriter);
125	
126	  rewriter.replaceOp(op, selectResult);
127	  return success();
128	}
