130	LogicalResult StoreConverter::matchAndRewrite(triton::StoreOp op,
131	                                              PatternRewriter &rewriter) const {
132	  auto loc = op.getLoc();
133	  auto oldPtr = op.getPtr();
134	  auto oldMask = op.getMask();
135	  auto oldValue = op.getValue();
136	
137	  MemOpTransformer tf(MemOpTransformer::MemType::store, optimizeDynamicOffset);
138	
139	  auto newPtr = tf.createNewPtr(oldPtr, loc, rewriter);
140	  auto newMask = tf.createNewMask(oldMask, loc, rewriter);
141	
142	  if (!tf.ptrState.shouldLinearize) {
143	    // no need to rewrite
144	    return failure();
145	  }
146	
147	  if (!newPtr) {
148	    LLVM_DEBUG({
149	      InFlightDiagnostic diag =
150	          emitWarning(loc) << "PtrAnalysis: failed to analyze store pointer.";
151	    });
152	    return failure();
153	  }
154	
155	  if (!enableMaskFallbackConversion && oldMask && !newMask) {
156	    LLVM_DEBUG({
157	      InFlightDiagnostic diag =
158	          emitWarning(loc) << "MaskAnalysis: failed to analyze store mask.";
159	    });
160	    return failure();
161	  }
162	
163	  // insert sync_block_lock
164	  auto lockVar = createSyncBlockLockVar(rewriter, loc);
165	  if (oldMask && !newMask) {
166	    rewriter.create<hivm::SyncBlockLockOp>(loc, lockVar);
167	  }
168	
169	  auto selectResult =
170	      tf.materializeImplicitSelect(oldValue, oldMask, oldPtr, loc, rewriter);
171	  auto reshapeResult =
172	      tf.materializeImplicitReshape(selectResult, loc, rewriter);
173	  auto permuteResult =
174	      tf.materializeImplicitPermute(reshapeResult, loc, rewriter);
175	
176	  auto storeOp = rewriter.create<triton::StoreOp>(
177	      loc, newPtr, permuteResult, newMask, op.getBoundaryCheck(), op.getCache(),
178	      op.getEvict());
179	
180	  // insert sync_block_unlock
181	  if (oldMask && !newMask) {
182	    rewriter.create<hivm::SyncBlockUnlockOp>(loc, lockVar);
183	  }
184	  rewriter.eraseOp(op);
185	  return success();
186	}
