188	Value MemOpTransformer::materializeImplicitBroadcast(
189	    Value srcTensor, const Location loc, PatternRewriter &rewriter) {
190	  SmallVector<int64_t> broadCastIndex;
191	  SmallVector<int64_t> broadCastShape;
192	  for (auto [i, info] : llvm::enumerate(ptrState.stateInfo)) {
193	    if (isZero(info.stride)) {
194	      broadCastIndex.emplace_back(i);
195	    }
196	    auto staticShape = getIntAttr(info.shape);
197	    if (!staticShape.has_value()) {
198	      LLVM_DEBUG({
199	        InFlightDiagnostic diag =
200	            emitWarning(loc)
201	            << "PtrAnalysis: dynamic shape is not supported in broadcast\n";
202	      });
203	      return srcTensor;
204	    }
205	    broadCastShape.emplace_back(staticShape.value());
206	  }
207	
208	  if (broadCastIndex.empty())
209	    return srcTensor;
210	
211	  // when load is a scalar, we need to use splat to broadcast
212	  auto srcType = srcTensor.getType();
213	  if (srcType.isIntOrFloat()) {
214	    auto broadCastType = RankedTensorType::get(broadCastShape, srcType);
215	    auto splatOp =
216	        rewriter.create<triton::SplatOp>(loc, broadCastType, srcTensor);
217	    return splatOp.getResult();
218	  }
219	
220	  auto init = rewriter.create<tensor::EmptyOp>(
221	      loc, broadCastShape,
222	      cast<ShapedType>(srcTensor.getType()).getElementType());
223	
224	  auto broadCastOp = rewriter.create<linalg::BroadcastOp>(loc, srcTensor, init,
225	                                                          broadCastIndex);
226	
227	  return broadCastOp->getResult(0);
228	}
