230	Value MemOpTransformer::materializeImplicitReshape(Value srcTensor,
231	                                                   const Location loc,
232	                                                   PatternRewriter &rewriter) {
233	  if (ptrState.sizes.size() == ptrState.stateInfo.size())
234	    return srcTensor;
235	  SmallVector<int64_t> targetShape;
236	  if (currentType == MemType::load) {
237	    for (auto size : ptrState.sizes) {
238	      auto staticShape = getIntAttr(size);
239	      if (!staticShape.has_value()) {
240	        LLVM_DEBUG({
241	          InFlightDiagnostic diag =
242	              emitWarning(loc)
243	              << "PtrAnalysis: dynamic shape is not supported in reshape\n";
244	        });
245	        return srcTensor;
246	      }
247	      targetShape.emplace_back(staticShape.value());
248	    }
249	  } else {
250	    for (auto info : ptrState.stateInfo) {
251	      auto staticShape = getIntAttr(info.shape);
252	      if (!staticShape.has_value()) {
253	        LLVM_DEBUG({
254	          InFlightDiagnostic diag =
255	              emitWarning(loc)
256	              << "PtrAnalysis: dynamic shape is not supported in reshape\n";
257	        });
258	        return srcTensor;
259	      }
260	      targetShape.emplace_back(staticShape.value());
261	    }
262	  }
263	
264	  auto targetShapeAttr = DenseIntElementsAttr::get(
265	      RankedTensorType::get({static_cast<int64_t>(targetShape.size())},
266	                            rewriter.getI64Type()),
267	      targetShape);
268	  auto targetShapeType = RankedTensorType::get(
269	      targetShape, cast<ShapedType>(srcTensor.getType()).getElementType());
270	  auto targetShapeValue =
271	      rewriter.create<arith::ConstantOp>(loc, targetShapeAttr);
272	  auto reshapeOp = rewriter.create<tensor::ReshapeOp>(
273	      loc, targetShapeType, srcTensor, targetShapeValue);
274	  return reshapeOp.getResult();
275	}
