277	Value MemOpTransformer::materializeImplicitSelect(Value srcTensor, Value mask,
278	                                                  Value other,
279	                                                  const Location loc,
280	                                                  PatternRewriter &rewriter) {
281	  if (!mask || maskState.newMask)
282	    return srcTensor;
283	  auto TensorType = cast<RankedTensorType>(srcTensor.getType());
284	  if (cast<ShapedType>(mask.getType()).getShape() != TensorType.getShape()) {
285	    LLVM_DEBUG({
286	      InFlightDiagnostic diag =
287	          emitWarning(loc) << "MaskAnalysis: mask shape is not same as Value";
288	    });
289	    return srcTensor;
290	  }
291	
292	  if (currentType == MemType::store) {
293	    auto loadOp = rewriter.create<triton::LoadOp>(loc, other, nullptr, nullptr,
294	                                                  ArrayRef<int32_t>(), nullptr);
295	    other = loadOp.getResult();
296	  }
297	
298	  if (!other) {
299	    auto elementType = TensorType.getElementType();
300	    auto emptyOp = rewriter.create<tensor::EmptyOp>(loc, TensorType.getShape(),
301	                                                    elementType);
302	    other = emptyOp.getResult();
303	  }
304	  auto selectOp = rewriter.create<arith::SelectOp>(loc, mask, srcTensor, other);
305	  return selectOp->getResult(0);
306	}
307	
308	Value MemOpTransformer::materializeImplicitPermute(Value srcTensor,
309	                                                   const Location loc,
310	                                                   PatternRewriter &rewriter) {
311	  auto inTy = dyn_cast<RankedTensorType>(srcTensor.getType());
312	  if (!inTy || !ptrState.isPermuted)
313	    return srcTensor;
314	
315	  auto inShape = inTy.getShape();
316	  SmallVector<int32_t> order(ptrState.permuteIds.size());
317	  for (size_t i = 0; i < ptrState.permuteIds.size(); ++i) {
318	    if (currentType == MemType::load) {
319	      order[ptrState.permuteIds[i]] = i;
320	    } else {
321	      order[i] = ptrState.permuteIds[i];
322	    }
323	  }
324	  SmallVector<int64_t> outShape(order.size());
325	  if (inShape.size() != outShape.size()) {
326	    LLVM_DEBUG({
327	      InFlightDiagnostic diag =
328	          emitWarning(loc) << "PtrAnalysis: incompatible shape for permute";
329	    });
330	    return srcTensor;
331	  }
332	
333	  for (size_t i = 0; i < outShape.size(); ++i) {
334	    outShape[i] = inShape[order[i]];
335	  }
336	
337	  auto outTy = RankedTensorType::get(outShape, inTy.getElementType());
338	  auto transOp = rewriter.create<triton::TransOp>(loc, outTy, srcTensor, order);
339	  return transOp.getResult();
340	}
341	
342	Value MemOpTransformer::createNewPtr(Value oldPtr, const Location loc,
343	                                     PatternRewriter &rewriter) {
344	  TritonToStructured::PtrAnalysis ptrAnalysis(optimizeDynamicOffset);
345	
346	  LLVM_DEBUG({
347	    llvm::dbgs() << "----------------------------------------------\n";
348	    llvm::dbgs() << "PtrAnalysis: analyzing load/store's ptr.\n";
349	  });
350	
351	  if (ptrAnalysis.visitOperand(oldPtr, ptrState, loc, rewriter).failed()) {
352	    ptrState.shouldLinearize = false;
353	    LLVM_DEBUG({
354	      InFlightDiagnostic diag =
355	          emitWarning(loc) << "PtranAlysis: failed to analyze load/store ptr.";
356	    });
357	    return oldPtr;
358	  }
359	
360	  // compute missing strides
361	  // if stateinfo.shape is 1 and sizes[dimIndex] is 1,
362	  // then the stride is the accumulated size of all dimensions on the right side
363	  // ie. for shape [1, 128], sizes [1, 128], originally stride is [0, 1],
364	  // after normalization, stride is [128, 1]
365	  OpFoldResult maxStride = rewriter.getIndexAttr(1);
366	  for (auto it = ptrState.stateInfo.rbegin(); it != ptrState.stateInfo.rend();
367	       ++it) {
368	    if (TritonToStructured::isOne(it->shape) && isZero(it->stride)) {
369	      it->stride = maxStride;
370	    }
371	    maxStride = maxOpFoldResult(maxStride, it->stride, loc, rewriter);
372	  }
373	
374	  for (auto it = ptrState.stateInfo.rbegin(); it != ptrState.stateInfo.rend();
375	       ++it) {
376	    if (isZero(it->stride)) {
377	      ptrState.shouldLinearize = true;
378	    }
379	  }
380	
381	  ptrState.generateOriginPermuteIds();
382	
383	  return ptrState.createAddPtrOp(rewriter, loc);
384	}
385	
386	Value MemOpTransformer::createNewMask(Value oldMask, const Location loc,
387	                                      PatternRewriter &rewriter) {
388	  if (!oldMask)
389	    return nullptr;
390	
391	  LLVM_DEBUG({
392	    llvm::dbgs() << "----------------------------------------------\n";
393	    llvm::dbgs() << "MaskAnalysis: analyzing load/store mask.\n";
394	  });
395	
396	  if (!oldMask || maskState.analysisMask(oldMask).failed()) {
397	    LLVM_DEBUG({
398	      llvm::dbgs() << "----------------------------------------------\n";
399	      llvm::dbgs() << "MaskAnalysis: no mask or failed to analyze mask.\n";
400	      llvm::dbgs() << "oldMask:" << oldMask << "\n";
401	      maskState.dump();
402	      llvm::dbgs() << "----------------------------------------------\n";
403	    });
404	    LLVM_DEBUG(
405	        {
406	          InFlightDiagnostic diag =
407	              emitWarning(loc)
408	              << "MaskAnalysis: failed to analyze load/store mask.";
409	        });
410	    return nullptr;
411	  }
412	
413	  SmallVector<TritonToStructured::dimInfo> newMaskInfo;
414	  auto itPtr = ptrState.stateInfo.begin();
415	  auto itMask = maskState.stateInfo.begin();
416	
417	  // match and create new mask info
418	  while (itPtr != ptrState.stateInfo.end() &&
419	         itMask != maskState.stateInfo.end()) {
420	    // ptr'shape must be multiple of mask'shape or vice versa
421	    if (!isMultiple(itMask->shape, itPtr->shape)) {
422	      LLVM_DEBUG({
423	        InFlightDiagnostic diag =
424	            emitWarning(loc)
425	            << "MaskAnalysis: incompatible shapes between ptr and mask.";
426	        llvm::dbgs() << "----------------------------------------------\n";
427	        ptrState.dump();
428	        llvm::dbgs() << "oldMask:" << oldMask << "\n";
429	        maskState.dump();
430	        llvm::dbgs() << "----------------------------------------------\n";
431	      });
432	      return nullptr;
433	    }
434	
435	    auto newShape = minOpFoldResult(itMask->shape, itPtr->shape, loc, rewriter);
436	    if (isLess(newShape, itMask->shape) && !itMask->hasBroadCast) {
437	      LLVM_DEBUG({
438	        InFlightDiagnostic diag =
439	            emitWarning(loc)
440	            << "MaskAnalysis: the mask shape is incompatible with ptr shape.";
441	      });
442	      return nullptr;
443	    }
444	
445	    TritonToStructured::dimInfo newInfo(itMask->offset, newShape,
446	                                        itMask->dimIndex, itMask->hasBroadCast,
447	                                        itMask->currentType, itMask->rhs);
448	
449	    if (!isZero(itPtr->stride)) {
450	      newMaskInfo.emplace_back(newInfo);
451	    }
452	
453	    ++itPtr;
454	    if (isEqual(itMask->shape, newShape)) {
455	      ++itMask;
456	    }
457	  }
458	
459	  if (itPtr != ptrState.stateInfo.end() ||
460	      itMask != maskState.stateInfo.end()) {
461	    LLVM_DEBUG({
462	      llvm::dbgs() << "----------------------------------------------\n";
463	      llvm::dbgs() << "MaskAnalysis: failed to apply permute on mask.\n";
464	      ptrState.dump();
465	      llvm::dbgs() << "oldMask:" << oldMask << "\n";
466	      maskState.dump();
467	      llvm::dbgs() << "----------------------------------------------\n";
468	    });
469	    LLVM_DEBUG({
470	      InFlightDiagnostic diag = emitWarning(loc)
471	                                << "MaskAnalysis: incompatible number of "
472	                                   "dimensions between ptr and mask.";
473	    });
474	    return nullptr;
475	  }
476	
477	  maskState.stateInfo = newMaskInfo;
478	
479	  if (ptrState.isPermuted && !applyPermuteOnMask()) {
480	    LLVM_DEBUG({
481	      llvm::dbgs() << "----------------------------------------------\n";
482	      llvm::dbgs() << "MaskAnalysis: failed to apply permute on mask.\n";
483	      ptrState.dump();
484	      llvm::dbgs() << "oldMask:" << oldMask << "\n";
485	      maskState.dump();
486	      llvm::dbgs() << "----------------------------------------------\n";
487	      InFlightDiagnostic diag =
488	          emitWarning(loc) << "MaskAnalysis: failed to apply permute on mask.";
489	    });
490	    return nullptr;
491	  }
492	
493	  LLVM_DEBUG({
494	    llvm::dbgs() << "After matching MaskState: \n";
495	    for (auto info : newMaskInfo) {
496	      info.dump();
497	    }
498	    llvm::dbgs() << "----------------------------------------------\n";
499	  });
500	
501	  auto newMask = maskState.createNewMask(loc, rewriter);
502	  return newMask;
503	}
504	
505	Value MemOpTransformer::createNewOther(Value oldOther, const Location loc,
506	                                       PatternRewriter &rewriter) {
507	  if (!oldOther || !maskState.newMask)
508	    return nullptr;
509	
510	  auto ptrType = dyn_cast<triton::PointerType>(ptrState.source.getType());
511	  if (!ptrType) {
512	    LLVM_DEBUG(
513	        {
514	          InFlightDiagnostic diag =
515	              emitWarning(loc)
516	              << "PtrAnalysis: source of ptrState is not a pointer type.";
517	        });
518	    return nullptr;
519	  }
520	  Type elementType = ptrType.getPointeeType();
521	
522	  SmallVector<int64_t> targetShape;
523	  for (auto info : maskState.stateInfo) {
524	    auto staticShape = getIntAttr(info.shape);
525	    if (!staticShape.has_value()) {
526	      LLVM_DEBUG({
527	        InFlightDiagnostic diag =
528	            emitWarning(loc)
529	            << "MaskAnalysis: dynamic shape is not supported in reshape\n";
530	      });
531	      return oldOther;
532	    }
533	    targetShape.emplace_back(staticShape.value());
534	  }
535	  auto targetShapeAttr = DenseIntElementsAttr::get(
536	      RankedTensorType::get({static_cast<int64_t>(targetShape.size())},
537	                            rewriter.getI64Type()),
538	      targetShape);
539	  auto targetShapeType = RankedTensorType::get(targetShape, elementType);
540	  auto targetShapeValue =
541	      rewriter.create<arith::ConstantOp>(loc, targetShapeAttr);
542	
543	  auto reshapeOp = rewriter.create<tensor::ReshapeOp>(
544	      loc, targetShapeType, oldOther, targetShapeValue);
545	
546	  return reshapeOp.getResult();
547	}
548	
549	bool MemOpTransformer::applyPermuteOnMask() {
550	  if (!ptrState.isPermuted || maskState.isEmpty()) {
551	    return true;
552	  }
553	  if (ptrState.permuteIds.size() != maskState.stateInfo.size()) {
554	    return false;
555	  }
556	  SmallVector<TritonToStructured::dimInfo> newMaskInfo;
557	  for (auto id : ptrState.permuteIds) {
558	    newMaskInfo.push_back(maskState.stateInfo[id]);
559	  }
560	  maskState.stateInfo = newMaskInfo;
561	  return true;
562	}
563	
564	hivm::CreateSyncBlockLockOp createSyncBlockLockVar(OpBuilder &builder,
565	                                                   Location loc) {
566	  SmallVector<int64_t> shape = {1};
567	  auto elementType = builder.getI64Type();
568	  Type memrefType = MemRefType::get(shape, elementType);
569	
570	  auto createSyncBlockLockOp =
571	      builder.create<hivm::CreateSyncBlockLockOp>(loc, memrefType, Value());
572	  return createSyncBlockLockOp;
573	}
574	} // namespace MemOpConverter
