124	LogicalResult MaskState::parse(Value operand, const Location loc,
125	                               OpBuilder &builder) {
126	  if (isa<IntegerType>(operand.getType()) &&
127	      operand.getType().getIntOrFloatBitWidth() != 1) {
128	    return this->parseIntScalar(operand, loc, builder);
129	  } else if (auto op = operand.getDefiningOp<arith::ConstantOp>()) {
130	    return this->parseConstant(op, loc, builder);
131	  } else if (auto op = operand.getDefiningOp<arith::AddIOp>()) {
132	    return this->parseAdd(op, loc, builder);
133	  } else if (auto op = operand.getDefiningOp<arith::AndIOp>()) {
134	    return this->parseAnd(op, loc, builder);
135	  } else if (auto op = operand.getDefiningOp<arith::CmpIOp>()) {
136	    return this->parseCmp(op, loc, builder);
137	  } else if (auto op = operand.getDefiningOp<triton::MakeRangeOp>()) {
138	    return this->parseMakeRange(op, loc, builder);
139	  } else if (auto op = operand.getDefiningOp<triton::BroadcastOp>()) {
140	    return this->parseBroadcast(op, loc, builder);
141	  } else if (auto op = operand.getDefiningOp<triton::SplatOp>()) {
142	    return this->parseSplat(op, loc, builder);
143	  } else if (auto op = operand.getDefiningOp<triton::ExpandDimsOp>()) {
144	    return this->parseExpandDims(op, loc, builder);
145	  } else if (auto op = operand.getDefiningOp<arith::ExtSIOp>()) {
146	    return this->parseExtSI(op, loc, builder);
147	  } else if (auto op = operand.getDefiningOp<arith::RemSIOp>()) {
148	    return this->parseRem(op, loc, builder);
149	  } else if (auto op = operand.getDefiningOp<arith::DivSIOp>()) {
150	    return this->parseDiv(op, loc, builder);
151	  }
152	  LLVM_DEBUG({
153	    InFlightDiagnostic diag = emitWarning(loc)
154	                              << "MaskAnalysis: compare operand produced by an "
155	                                 "unsupported operation\n";
156	  });
157	  return failure();
158	}
159	
160	LogicalResult MaskState::parseConstant(arith::ConstantOp constOp,
161	                                       const Location loc, OpBuilder &builder) {
162	  if (!this->isEmpty()) {
163	    LLVM_DEBUG({
164	      constOp.emitError(
165	          "MaskAnalysis: MaskState should be empty when visiting constant");
166	    });
167	    return failure();
168	  }
169	
170	  if (auto intType = dyn_cast<IntegerType>(constOp.getType())) {
171	    if (intType.getWidth() == 1) {
172	      LLVM_DEBUG({
173	        constOp.emitWarning("MaskAnalysis: Unsupported constant for int1");
174	      });
175	      return failure();
176	    }
177	  }
178	
179	  if (isa<DenseElementsAttr>(constOp.getValue())) {
180	    auto attr = cast<DenseElementsAttr>(constOp.getValue());
181	    auto elementType = attr.getElementType();
182	    if (!attr.isSplat() || !isa<IntegerType>(elementType)) {
183	      LLVM_DEBUG({
184	        constOp.emitError("MaskAnalysis: only support splat integer constant");
185	      });
186	      return failure();
187	    }
188	    auto values = attr.getValues<IntegerAttr>();
189	    auto value = values[0].getValue();
190	    auto constAttr = builder.getIndexAttr(value.getSExtValue());
191	    auto op = arith::ConstantOp::materialize(builder, constAttr,
192	                                             builder.getIndexType(), loc);
193	    this->scalar = op.getValue();
194	  } else {
195	    auto value = cast<IntegerAttr>(constOp.getValue()).getInt();
196	    this->scalar = builder.getIndexAttr(value);
197	  }
198	  return success();
199	}
