201	LogicalResult MaskState::parseIntScalar(Value scalar, const Location loc,
202	                                        OpBuilder &builder) {
203	  if (!this->isEmpty()) {
204	    LLVM_DEBUG({
205	      InFlightDiagnostic diag =
206	          emitError(loc) << "MaskAnalysis: MaskState should be empty when "
207	                            "visiting integer scalar";
208	    });
209	    return failure();
210	  }
211	  auto castOp =
212	      builder.create<arith::IndexCastOp>(loc, builder.getIndexType(), scalar);
213	  this->scalar = castOp.getResult();
214	  return success();
215	}
