217	LogicalResult MaskState::parseMakeRange(triton::MakeRangeOp rangeOp,
218	                                        const Location loc,
219	                                        OpBuilder &builder) {
220	  if (!this->isEmpty()) {
221	    LLVM_DEBUG({
222	      rangeOp.emitError(
223	          "MaskAnalysis: MaskState should be empty when visiting make_range");
224	    });
225	    return failure();
226	  }
227	
228	  auto shape = cast<ShapedType>(rangeOp.getType()).getShape();
229	  auto start = rangeOp.getStart();
230	  auto end = rangeOp.getEnd();
231	  auto stride = (end - start + shape[0] - 1) / shape[0];
232	
233	  if (stride != 1) {
234	    LLVM_DEBUG(
235	        {
236	          InFlightDiagnostic diag =
237	              emitError(loc)
238	              << "stride must be 1 for make_range whose result is used "
239	                 "as load or store masks";
240	        });
241	    return failure();
242	  }
243	
244	  stateInfo.emplace_back(builder.getIndexAttr(start),
245	                         builder.getIndexAttr(shape[0]));
246	  return success();
247	}
