261	LogicalResult MaskState::parseSplat(triton::SplatOp splatOp, const Location loc,
262	                                    OpBuilder &builder) {
263	  if (!this->isEmpty()) {
264	    LLVM_DEBUG({
265	      splatOp.emitError(
266	          "MaskAnalysis: MaskState should be empty when visiting splat");
267	    });
268	    return failure();
269	  }
270	
271	  auto src = splatOp.getSrc();
272	  auto dst = splatOp.getResult();
273	  auto dstShape = cast<ShapedType>(dst.getType()).getShape();
274	
275	  if (!isa<IntegerType>(src.getType())) {
276	    LLVM_DEBUG(
277	        {
278	          splatOp.emitError()
279	              << "splat source must be an integer scalar for load/store masks";
280	        });
281	    return failure();
282	  }
283	
284	  if (failed(this->parse(src, loc, builder)))
285	    return failure();
286	
287	  if (stateInfo.size() > 1 ||
288	      (stateInfo.size() == 1 && !isOne(stateInfo.back().shape))) {
289	    LLVM_DEBUG({
290	      splatOp.emitError() << "splat from a non-scalar source is not supported, "
291	                             "unless it's state size and shape are 1";
292	    });
293	    return failure();
294	  }
295	
296	  auto zeroAttr = builder.getIndexAttr(0);
297	  SmallVector<dimInfo> newStateInfo;
298	  for (auto [i, shape] : llvm::enumerate(dstShape)) {
299	    auto shapeAttr = builder.getIndexAttr(shape);
300	    newStateInfo.emplace_back(zeroAttr, shapeAttr, i, true);
301	    if (!stateInfo.empty() && shape == 1) {
302	      newStateInfo.back() = stateInfo.back();
303	      newStateInfo.back().dimIndex = i;
304	    }
305	  }
306	  this->stateInfo = newStateInfo;
307	  return success();
308	}
309	
310	LogicalResult MaskState::parseExpandDims(triton::ExpandDimsOp expandDimsOp,
311	                                         const Location loc,
312	                                         OpBuilder &builder) {
313	  if (!this->isEmpty()) {
314	    LLVM_DEBUG({
315	      expandDimsOp.emitError(
316	          "MaskAnalysis: MaskState should be empty when visiting expand_dims");
317	    });
318	    return failure();
319	  }
320	
321	  auto zeroAttr = builder.getIndexAttr(0);
322	  auto defaultShape = builder.getIndexAttr(1);
323	
324	  if (failed(this->parse(expandDimsOp.getSrc(), loc, builder)))
325	    return failure();
326	
327	  auto dstShape =
328	      cast<ShapedType>(expandDimsOp.getResult().getType()).getShape();
329	  auto axis = expandDimsOp.getAxis();
330	  if (dstShape[axis] != 1) {
331	    LLVM_DEBUG({
332	      expandDimsOp.emitError(
333	          "MaskAnalysis: unexpected dimension size in expand_dims");
334	    });
335	    return failure();
336	  }
337	
338	  size_t insertPos = 0;
339	  for (auto &info : stateInfo) {
340	    if (info.dimIndex >= axis)
341	      ++info.dimIndex;
342	    if (info.dimIndex < axis)
343	      ++insertPos;
344	  }
345	
346	  dimInfo insertInfo(zeroAttr, defaultShape, axis, true);
347	  stateInfo.insert(stateInfo.begin() + insertPos, insertInfo);
348	
349	  return success();
350	}
