352	LogicalResult MaskState::parseAdd(arith::AddIOp addOp, const Location loc,
353	                                  OpBuilder &builder) {
354	  if (!this->isEmpty()) {
355	    LLVM_DEBUG({
356	      addOp.emitError(
357	          "MaskAnalysis: MaskState should be empty when visiting add");
358	    });
359	    return failure();
360	  }
361	
362	  MaskState lhsState;
363	  if (failed(lhsState.parse(addOp.getLhs(), loc, builder)))
364	    return failure();
365	
366	  MaskState rhsState;
367	  if (failed(rhsState.parse(addOp.getRhs(), loc, builder)))
368	    return failure();
369	
370	  return this->addStates(lhsState, rhsState, loc, builder);
371	}
