373	LogicalResult MaskState::addStates(const MaskState &lhsState,
374	                                   const MaskState &rhsState, Location loc,
375	                                   OpBuilder &builder) {
376	  if (lhsState.scalar && rhsState.scalar) {
377	    LLVM_DEBUG(
378	        {
379	          InFlightDiagnostic diag =
380	              emitWarning(loc)
381	              << "Unexpected case where both lhs and rhs are scalars";
382	        });
383	    return failure();
384	  }
385	
386	  if (!lhsState.scalar && !rhsState.scalar) {
387	    LLVM_DEBUG(
388	        {
389	          InFlightDiagnostic diag =
390	              emitWarning(loc)
391	              << "Unsupported scenario where neither lhs nor rhs is a scalar";
392	        });
393	    return failure();
394	  }
395	
396	  if (lhsState.scalar)
397	    return addStateScalar(rhsState, lhsState.scalar, loc, builder);
398	  else
399	    return addStateScalar(lhsState, rhsState.scalar, loc, builder);
400	}
401	
402	LogicalResult MaskState::addStateScalar(const MaskState &state,
403	                                        const OpFoldResult scalar, Location loc,
404	                                        OpBuilder &builder) {
405	  for (auto info : state.stateInfo) {
406	    info.offset = addOpFoldResult(info.offset, scalar, loc, builder);
407	    this->stateInfo.emplace_back(info);
408	  }
409	  return success();
410	}
411	
412	LogicalResult MaskState::parseBroadcast(triton::BroadcastOp broadcastOp,
413	                                        const Location loc,
414	                                        OpBuilder &builder) {
415	  if (!this->isEmpty()) {
416	    LLVM_DEBUG({
417	      broadcastOp.emitError(
418	          "MaskAnalysis: MaskState should be empty when visiting broadcast");
419	    });
420	    return failure();
421	  }
422	
423	  LLVM_DEBUG({
424	    llvm::dbgs() << "----------------------------------------------\n";
425	    llvm::dbgs() << "Parsing BROADCAST operation: " << broadcastOp << "\n";
426	  });
427	
428	  auto src = broadcastOp.getSrc();
429	  auto dst = broadcastOp.getResult();
430	  if (!isa<ShapedType>(dst.getType())) {
431	    LLVM_DEBUG({
432	      broadcastOp.emitError(
433	          "MaskAnalysis: broadcast dst should be a shaped type");
434	    });
435	    return failure();
436	  }
437	
438	  auto srcShape = cast<ShapedType>(src.getType()).getShape();
439	  auto dstShape = cast<ShapedType>(dst.getType()).getShape();
440	  if (srcShape.size() != dstShape.size()) {
441	    LLVM_DEBUG({
442	      broadcastOp.emitError(
443	          "MaskAnalysis: broadcast src and dst should have the same rank");
444	    });
445	    return failure();
446	  }
447	
448	  if (failed(parse(src, loc, builder)))
449	    return failure();
450	
451	  LLVM_DEBUG({
452	    llvm::dbgs() << "Before BROADCAST MaskState: \n";
453	    this->dump();
454	  });
455	
456	  for (size_t i = 0; i < srcShape.size(); ++i) {
457	    if (srcShape[i] == dstShape[i])
458	      continue;
459	    else if (srcShape[i] < dstShape[i] && srcShape[i] == 1) {
460	      for (auto &info : stateInfo) {
461	        if (info.dimIndex != i)
462	          continue;
463	        info.shape = builder.getIndexAttr(dstShape[i]);
464	        info.hasBroadCast = true;
465	      }
466	    } else {
467	      LLVM_DEBUG({
468	        broadcastOp.emitError(
469	            "MaskAnalysis: unexpected dimensions used in broadcast");
470	      });
471	      return failure();
472	    }
473	  }
474	
475	  LLVM_DEBUG({
476	    llvm::dbgs() << "After BROADCAST MaskState: \n";
477	    this->dump();
478	    llvm::dbgs() << "----------------------------------------------\n";
479	  });
480	
481	  return success();
482	}
483	
484	LogicalResult MaskState::parseCmp(arith::CmpIOp cmpOp, const Location loc,
485	                                  OpBuilder &builder) {
486	  if (!this->isEmpty()) {
487	    LLVM_DEBUG({
488	      cmpOp.emitError(
489	          "MaskAnalysis: MaskState should be empty when visiting cmpi");
490	    });
491	    return failure();
492	  }
493	  LLVM_DEBUG({
494	    llvm::dbgs() << "----------------------------------------------\n";
495	    llvm::dbgs() << "Parsing CMP operation: " << cmpOp << "\n";
496	  });
497	
498	  if (isa<IntegerType>(cmpOp.getLhs().getType()) &&
499	      (cmpOp.getLhs().getDefiningOp<arith::CmpIOp>() ||
500	       cmpOp.getRhs().getDefiningOp<arith::CmpIOp>())) {
501	    LLVM_DEBUG({
502	      cmpOp.emitWarning(
503	          "MaskAnalysis: Unsupported nested cmpi scenario for int1");
504	    });
505	    return failure();
506	  }
507	
508	  MaskState lhsState;
509	  if (failed(lhsState.parse(cmpOp.getLhs(), loc, builder)))
510	    return failure();
511	
512	  MaskState rhsState;
513	  if (failed(rhsState.parse(cmpOp.getRhs(), loc, builder)))
514	    return failure();
515	
516	  if (lhsState.scalar) {
517	    if (lhsState.stateInfo.empty()) {
518	      lhsState.stateInfo.emplace_back(builder.getIndexAttr(0),
519	                                      builder.getIndexAttr(1));
520	    }
521	    for (auto &info : lhsState.stateInfo) {
522	      if (isOne(info.shape)) {
523	        info.offset = lhsState.scalar;
524	      }
525	    }
526	  }
527	
528	  // lhs must be a Value and rhs must be scalar
529	  if (!rhsState.scalar) {
530	    LLVM_DEBUG(
531	        { cmpOp.emitWarning("MaskAnalysis: Unsupported cmpi scenario"); });
532	    return failure();
533	  }
534	
535	  LLVM_DEBUG({
536	    llvm::dbgs() << "LHS MaskState: \n";
537	    lhsState.dump();
538	    llvm::dbgs() << "RHS MaskState: \n";
539	    rhsState.dump();
540	    llvm::dbgs() << "----------------------------------------------\n";
541	  });
542	
543	  // In the case where the values we are loading are entirely masked off like
544	  // the following:
545	  //
546	  // ---|-------|-----------|
547	  //    ^       ^           ^
548	  //   scalar  start       end
549	  //
550	  // newEnd = min(end, scalar) = scalar
551	  // Now scalar < start, so simply doing dim = newEnd - start is incorrect.
552	  //
553	  // The correct formula is to optionally move `newDim` back to `start` using
554	  // max(newEnd, start).
555	  auto cmpType = cmpOp.getPredicate();
556	  for (auto &info : lhsState.stateInfo) {
557	    if (info.hasBroadCast)
558	      continue;
559	    if (!info.setType(cmpType)) {
560	      LLVM_DEBUG({ cmpOp.emitWarning("MaskAnalysis: Unsupported cmpi type"); });
561	      return failure();
562	    }
563	    info.rhs = rhsState.scalar;
564	  }
565	  this->stateInfo = lhsState.stateInfo;
566	
567	  LLVM_DEBUG({
568	    llvm::dbgs() << "After CMP MaskState: \n";
569	    this->dump();
570	    llvm::dbgs() << "----------------------------------------------\n";
571	  });
572	  return success();
573	}
574	
575	LogicalResult MaskState::parseRem(arith::RemSIOp remOp, const Location loc,
576	                                  OpBuilder &builder) {
577	  if (!this->isEmpty()) {
578	    LLVM_DEBUG({
579	      remOp.emitError(
580	          "MaskAnalysis: MaskState should be empty when visiting REMSI");
581	    });
582	    return failure();
583	  }
584	
585	  MaskState lhsState;
586	  if (failed(lhsState.parse(remOp.getLhs(), loc, builder)))
587	    return failure();
588	
589	  MaskState rhsState;
590	  if (failed(rhsState.parse(remOp.getRhs(), loc, builder)))
591	    return failure();
592	
593	  if (lhsState.scalar || !rhsState.scalar) {
594	    LLVM_DEBUG(
595	        { remOp.emitRemark("MaskAnalysis: Unsupported REMSI scenario"); });
596	    return failure();
597	  }
598	
599	  auto divisorAttr = rhsState.scalar;
600	
601	  if (!getIntAttr(divisorAttr).has_value()) {
602	    LLVM_DEBUG({
603	      remOp.emitError("MaskAnalysis: do not support dynamic divisor in REMSI.");
604	    });
605	    return failure();
606	  }
607	
608	  SmallVector<dimInfo> newStateInfo;
609	  auto zeroAttr = builder.getIndexAttr(0);
610	  for (auto info : lhsState.stateInfo) {
611	    if (info.hasBroadCast) {
612	      newStateInfo.emplace_back(info);
613	      continue;
614	    }
615	    if (!isMultiple(divisorAttr, info.shape) &&
616	        !isMultiple(info.shape, divisorAttr)) {
617	      LLVM_DEBUG({
618	        remOp.emitError(
619	            "MaskAnalysis: do not support dynamic stride before REMSI.");
620	      });
621	      return failure();
622	    }
623	
624	    auto contiguousSize =
625	        minOpFoldResult(divisorAttr, info.shape, loc, builder);
626	    auto nonContiguousSize =
627	        divOpFoldResult(info.shape, contiguousSize, loc, builder);
628	
629	    auto staticNonContiguousSize = getIntAttr(nonContiguousSize);
630	    if (!staticNonContiguousSize.has_value()) {
631	      LLVM_DEBUG({
632	        remOp.emitError(
633	            "MaskAnalysis: do not support dynamic size before REMSI.");
634	      });
635	      return failure();
636	    }
637	
638	    if (staticNonContiguousSize.value() != 0)
639	      newStateInfo.emplace_back(zeroAttr, nonContiguousSize, info.dimIndex,
640	                                true);
641	
642	    auto newOffset = remOpFoldResult(info.offset, divisorAttr, loc, builder);
643	    newStateInfo.emplace_back(newOffset, nonContiguousSize, info.dimIndex);
644	  }
645	
646	  this->stateInfo = newStateInfo;
647	
648	  return success();
649	}
650	
651	LogicalResult MaskState::parseDiv(arith::DivSIOp divOp, const Location loc,
652	                                  OpBuilder &builder) {
653	  if (!this->isEmpty()) {
654	    LLVM_DEBUG({
655	      divOp.emitError(
656	          "MaskAnalysis: MaskState should be empty when visiting DIVSI");
657	    });
658	    return failure();
659	  }
660	
661	  LLVM_DEBUG({
662	    llvm::dbgs() << "----------------------------------------------\n";
663	    llvm::dbgs() << "Parsing DIV operation: " << divOp << "\n";
664	  });
665	
666	  MaskState lhsState;
667	  if (failed(lhsState.parse(divOp.getLhs(), loc, builder)))
668	    return failure();
669	
670	  MaskState rhsState;
671	  if (failed(rhsState.parse(divOp.getRhs(), loc, builder)))
672	    return failure();
673	
674	  LLVM_DEBUG({
675	    llvm::dbgs() << "LHS MaskState: \n";
676	    lhsState.dump();
677	    llvm::dbgs() << "RHS MaskState: \n";
678	    rhsState.dump();
679	    llvm::dbgs() << "----------------------------------------------\n";
680	  });
681	
682	  if (lhsState.scalar || !rhsState.scalar) {
683	    LLVM_DEBUG(
684	        { divOp.emitRemark("MaskAnalysis: Unsupported DIVSI scenario"); });
685	    return failure();
686	  }
687	
688	  auto divisorAttr = rhsState.scalar;
689	
690	  if (!getIntAttr(divisorAttr).has_value()) {
691	    LLVM_DEBUG({
692	      divOp.emitError("MaskAnalysis: do not support dynamix divisor in DIVSI.");
693	    });
694	    return failure();
695	  }
696	
697	  SmallVector<dimInfo> newStateInfo;
698	  auto zeroAttr = builder.getIndexAttr(0);
699	  for (auto info : lhsState.stateInfo) {
700	    if (info.hasBroadCast) {
701	      newStateInfo.emplace_back(info);
702	      continue;
703	    }
704	    if (!isMultiple(divisorAttr, info.shape) &&
705	        !isMultiple(info.shape, divisorAttr)) {
706	      LLVM_DEBUG({
707	        divOp.emitError(
708	            "MaskAnalysis: do not support dynamix stride before DIVSI.");
709	      });
710	      return failure();
711	    }
712	
713	    auto nonContiguousSize =
714	        minOpFoldResult(divisorAttr, info.shape, loc, builder);
715	    auto contiguousSize =
716	        divOpFoldResult(info.shape, nonContiguousSize, loc, builder);
717	
718	    auto staticContiguousSize = getIntAttr(contiguousSize);
719	    if (!staticContiguousSize.has_value()) {
720	      LLVM_DEBUG({
721	        divOp.emitError(
722	            "MaskAnalysis: do not support dynamix size before DIVSI.");
723	      });
724	      return failure();
725	    }
726	
727	    if (staticContiguousSize.value() != 0) {
728	      auto newOffset = divOpFoldResult(info.offset, divisorAttr, loc, builder);
729	      newStateInfo.emplace_back(newOffset, contiguousSize, info.dimIndex);
730	    }
731	
732	    newStateInfo.emplace_back(zeroAttr, nonContiguousSize, info.dimIndex, true);
733	  }
734	
735	  this->stateInfo = newStateInfo;
736	
737	  LLVM_DEBUG({
738	    llvm::dbgs() << "After DIV MaskState: \n";
739	    this->dump();
740	    llvm::dbgs() << "----------------------------------------------\n";
741	  });
742	  return success();
743	}
744	
745	LogicalResult MaskState::parseAnd(arith::AndIOp andOp, const Location loc,
746	                                  OpBuilder &builder) {
747	  if (!this->isEmpty()) {
748	    LLVM_DEBUG({
749	      andOp.emitError(
750	          "MaskAnalysis: MaskState should be empty when visiting and");
751	    });
752	    return failure();
753	  }
754	  auto zeroAttr = builder.getIndexAttr(0);
755	
756	  LLVM_DEBUG({
757	    llvm::dbgs() << "----------------------------------------------\n";
758	    llvm::dbgs() << "Parsing AND operation: " << andOp << "\n";
759	  });
760	
761	  if (isa<IntegerType>(andOp.getLhs().getType())) {
762	    LLVM_DEBUG({
763	      andOp.emitWarning("MaskAnalysis: Unsupported andi scenario for int1");
764	    });
765	    return failure();
766	  }
767	
768	  MaskState lhsState;
769	  if (failed(lhsState.parse(andOp.getLhs(), loc, builder)))
770	    return failure();
771	  MaskState rhsState;
772	  if (failed(rhsState.parse(andOp.getRhs(), loc, builder)))
773	    return failure();
774	
775	  LLVM_DEBUG({
776	    llvm::dbgs() << "LHS MaskState: \n";
777	    lhsState.dump();
778	    llvm::dbgs() << "RHS MaskState: \n";
779	    rhsState.dump();
780	    llvm::dbgs() << "----------------------------------------------\n";
781	  });
782	
783	  SmallVector<dimInfo> newStateInfo;
784	  auto lIt = lhsState.stateInfo.begin();
785	  auto rIt = rhsState.stateInfo.begin();
786	
787	  while (lIt != lhsState.stateInfo.end() && rIt != rhsState.stateInfo.end()) {
788	    if (lIt->dimIndex != rIt->dimIndex) {
789	      auto newInfo = lIt->dimIndex < rIt->dimIndex ? *lIt++ : *rIt++;
790	      newStateInfo.emplace_back(newInfo);
791	      continue;
792	    }
793	
794	    if (!isMultiple(lIt->shape, rIt->shape) &&
795	        !isMultiple(rIt->shape, lIt->shape)) {
796	      LLVM_DEBUG({
797	        llvm::dbgs() << "LHS MaskState: \n";
798	        lhsState.dump();
799	        llvm::dbgs() << "RHS MaskState: \n";
800	        rhsState.dump();
801	        llvm::dbgs() << "----------------------------------------------\n";
802	      });
803	      LLVM_DEBUG({
804	        andOp.emitError(
805	            "MaskAnalysis: the add operation have incompatible sizes");
806	      });
807	      return failure();
808	    }
809	
810	    dimInfo newInfo;
811	    newInfo.dimIndex = lIt->dimIndex;
812	    newInfo.shape = minOpFoldResult(lIt->shape, rIt->shape, loc, builder);
813	    if ((isLess(newInfo.shape, lIt->shape) && !lIt->hasBroadCast ||
814	         isLess(newInfo.shape, rIt->shape) && !rIt->hasBroadCast)) {
815	      LLVM_DEBUG({
816	        llvm::dbgs() << "LHS MaskState: \n";
817	        lhsState.dump();
818	        llvm::dbgs() << "RHS MaskState: \n";
819	        rhsState.dump();
820	        llvm::dbgs() << "----------------------------------------------\n";
821	      });
822	      LLVM_DEBUG({
823	        andOp.emitError(
824	            "MaskAnalysis: the add operation have incompatible sizes."
825	            "Valid dimensions are split.");
826	      });
827	      return failure();
828	    }
829	    newInfo.currentType =
830	        lIt->hasBroadCast ? rIt->currentType : lIt->currentType;
831	    if (lIt->currentType != dimInfo::CompareType::deafaultType &&
832	        rIt->currentType != dimInfo::CompareType::deafaultType &&
833	        lIt->currentType != rIt->currentType) {
834	      LLVM_DEBUG({
835	        andOp.emitError(
836	            "MaskAnalysis: do not suppport different compare mode within"
837	            "the same dimension.");
838	      });
839	      return failure();
840	    }
841	
842	    if (lIt->hasBroadCast) {
843	      newInfo.offset = rIt->offset;
844	      newInfo.rhs = rIt->rhs;
845	      newInfo.hasBroadCast = rIt->hasBroadCast;
846	    } else if (rIt->hasBroadCast) {
847	      newInfo.offset = lIt->offset;
848	      newInfo.rhs = lIt->rhs;
849	      newInfo.hasBroadCast = lIt->hasBroadCast;
850	    } else {
851	      LLVM_DEBUG({
852	        andOp.emitError("MaskAnalysis: do not suppport "
853	                        "and in the same dimension.");
854	      });
855	      return failure();
856	    }
857	
858	    newStateInfo.emplace_back(newInfo);
859	
860	    if (isEqual(lIt->shape, newInfo.shape))
861	      ++lIt;
862	    else
863	      lIt->shape = divOpFoldResult(lIt->shape, newInfo.shape, loc, builder);
864	    if (isEqual(rIt->shape, newInfo.shape))
865	      ++rIt;
866	    else
867	      rIt->shape = divOpFoldResult(rIt->shape, newInfo.shape, loc, builder);
868	  }
869	
870	  while (rIt != rhsState.stateInfo.end()) {
871	    newStateInfo.push_back(*rIt++);
872	  }
873	  while (lIt != lhsState.stateInfo.end()) {
874	    newStateInfo.push_back(*lIt++);
875	  }
876	
877	  this->stateInfo = newStateInfo;
878	
879	  LLVM_DEBUG({
880	    llvm::dbgs() << "After AND MaskState: \n";
881	    this->dump();
882	    llvm::dbgs() << "----------------------------------------------\n";
883	  });
884	  return success();
885	}
886	
887	LogicalResult MaskState::analysisMask(Value operand) {
888	  auto op = operand.getDefiningOp();
889	  if (!op) {
890	    return failure();
891	  }
892	  auto loc = op->getLoc();
893	  OpBuilder builder(op);
894	
895	  LLVM_DEBUG({
896	    llvm::dbgs() << "----------------------------------------------\n";
897	    llvm::dbgs() << "Analyzing mask: " << operand << "\n";
898	  });
899	
900	  if (this->parse(operand, loc, builder).failed() || this->isEmpty()) {
901	    return failure();
902	  }
903	
904	  LLVM_DEBUG({
905	    llvm::dbgs() << "Mask analysis result: \n";
906	    this->dump();
907	    llvm::dbgs() << "MaskAnalysis: successfully analyzed mask.\n";
908	    llvm::dbgs() << "----------------------------------------------\n";
909	  });
910	  return success();
911	}
912	
913	Value MaskState::createNewMask(const Location loc, OpBuilder &builder) {
914	  if (isEmpty())
915	    return nullptr;
916	
917	  SmallVector<int64_t> shape;
918	  for (auto info : stateInfo) {
919	    auto staticShape = getIntAttr(info.shape);
920	    if (!staticShape.has_value()) {
921	      LLVM_DEBUG(
922	          {
923	            InFlightDiagnostic diag =
924	                emitError(loc)
925	                << "MaskAnalysis: dynamic shape is not supported in mask "
926	                   "generation\n";
927	          });
928	      return nullptr;
929	    }
930	    shape.emplace_back(staticShape.value());
931	  }
932	  SmallVector<Value> cacheResults;
933	  auto maskShape = RankedTensorType::get(shape, builder.getI1Type());
934	
935	  auto createRhsValue = [&](OpFoldResult rhs) -> Value {
936	    if (auto rhsInt = getIntAttr(rhs)) {
937	      auto rhsAttr =
938	          builder.getI32IntegerAttr(static_cast<int32_t>(rhsInt.value()));
939	      return builder.create<arith::ConstantOp>(loc, rhsAttr).getResult();
940	    }
941	    Value rhsValue = dyn_cast<Value>(rhs);
942	    if (rhsValue.getType().isIndex()) {
943	      rhsValue = builder.create<arith::IndexCastOp>(loc, builder.getI32Type(),
944	                                                    rhsValue);
945	    }
946	    return rhsValue;
947	  };
948	  for (size_t i = 0; i < stateInfo.size(); ++i) {
949	    auto info = stateInfo[i];
950	    if (info.hasBroadCast) {
951	      continue;
952	    }
953	    auto indexI32RowType =
954	        RankedTensorType::get(shape[i], builder.getI32Type());
955	    Value newMask =
956	        builder.create<triton::MakeRangeOp>(loc, indexI32RowType, 0, shape[i]);
957	
958	    Value newOffset = createRhsValue(info.offset);
959	    if (newOffset.getType().isIndex()) {
960	      newOffset = builder.create<arith::IndexCastOp>(loc, builder.getI32Type(),
961	                                                     newOffset);
962	    }
963	    Value splatRhs =
964	        builder.create<triton::SplatOp>(loc, indexI32RowType, newOffset);
965	    newMask = builder.create<arith::AddIOp>(loc, newMask, splatRhs);
966	
967	    auto rhsValue = createRhsValue(info.rhs);
968	    auto splatOp =
969	        builder.create<triton::SplatOp>(loc, indexI32RowType, rhsValue);
970	
971	    if (info.currentType == dimInfo::CompareType::deafaultType) {
972	      LLVM_DEBUG({
973	        InFlightDiagnostic diag = emitError(loc)
974	                                  << "MaskAnalysis: cannot generate mask when "
975	                                     "compare type is not set\n";
976	      });
977	      return nullptr;
978	    }
979	    auto cmpOp = builder.create<arith::CmpIOp>(loc,
980	                                               info.compareTypeIsLess()
981	                                                   ? arith::CmpIPredicate::slt
982	                                                   : arith::CmpIPredicate::sge,
983	                                               newMask, splatOp.getResult());
984	
985	    auto expandValue = cmpOp.getResult();
986	    for (size_t j = 0; j < stateInfo.size(); ++j) {
987	      if (j == i)
988	        continue;
989	      expandValue = builder.create<triton::ExpandDimsOp>(loc, expandValue, j);
990	    }
991	
992	    auto broadcastValue =
993	        builder.create<triton::BroadcastOp>(loc, maskShape, expandValue);
994	
995	    cacheResults.push_back(broadcastValue);
996	  }
997	
998	  if (cacheResults.empty()) {
999	    LLVM_DEBUG({
1000	      InFlightDiagnostic diag =
1001	          emitWarning(loc) << "MaskAnalysis: cannot generate mask when all "
1002	                              "dimensions are broadcasted";
1003	    });
1004	    return nullptr;
1005	  }
1006	  newMask = cacheResults[0];
1007	  for (size_t i = 1; i < cacheResults.size(); ++i) {
1008	    newMask = builder.create<arith::AndIOp>(loc, newMask, cacheResults[i]);
1009	  }
1010	  return newMask;
1011	}
1012	
1013	} // namespace TritonToStructured
