#ifndef TRITON_TO_STRUCTURED_PTRANALYSIS_H
#define TRITON_TO_STRUCTURED_PTRANALYSIS_H

#include <cstddef>
#include <set>

#include "mlir/Dialect/Arith/IR/Arith.h"
